(window.TRENER_PACKS=window.TRENER_PACKS||{})["zadanie-2-pshe"]={"id": "zadanie-2-pshe", "subject": "Химия", "title": "Задание 2 · Периодический закон и свойства элементов", "version": "26.11.2026", "konspekt": "zadanie-2-pshe", "codes": ["1.2"], "kod": {"p": [{"id": "p1", "t": "Периодический закон и чтение чёрно-белой таблицы ФИПИ", "x": "Свойства элементов и их соединений периодически зависят от заряда ядра Z (а не от атомной массы Ar), так как при росте Z повторяется строение внешнего электронного слоя. В чёрно-белой таблице ФИПИ элементы главной подгруппы (А) выровнены по тому же краю столбца, что и элементы 1–3 периодов, а большие периоды (4–7) занимают две строки.", "ref": "01.1"}, {"id": "p2", "t": "Атомный радиус, изоэлектронные ионы и энергия ионизации", "x": "По периоду слева направо число слоёв неизменно, а заряд ядра Z растёт — оболочка сжимается и радиус убывает. По главной подгруппе сверху вниз добавляются новые электронные слои — радиус растёт (к Fr/Cs). Энергия ионизации меняется противоположно радиусу: растёт вправо и вверх.", "ref": "02.1"}, {"id": "p3", "t": "Электроотрицательность, водород и благородные газы", "x": "Электроотрицательность (ЭО) — способность атома в соединении притягивать общие электроны; она растёт к фтору F (3,98). Тройка лидеров: F > O (3,44) > Cl (3,16) ≈ N (3,04). У благородных газов ЭО на ЕГЭ не сравнивается, а водород H (2,20) стоит между P и C (выше Si и B, но ниже C, S, N, O и галогенов).", "ref": "03.1"}, {"id": "p4", "t": "Компас металлических, неметаллических и ОВ-свойств", "x": "В задании № 2 металлические и восстановительные свойства атомов — синонимы: они усиливаются к Fr/Cs (влево и вниз, в т.ч. Li < Na < K). Неметаллические и окислительные свойства усиливаются к F (вправо и вверх, благородные газы исключены).", "ref": "04.1"}, {"id": "p5", "t": "Высшие оксиды и высшие гидроксиды: кислотность и основность", "x": "Высший гидроксид — это и основание/амфотерный гидроксид металла (NaOH, Al(OH)3), и высшая кислородсодержащая кислота неметалла (H2SO4, HNO3, H3PO4, HClO4). Основные свойства высших оксидов и гидроксидов растут к Fr (влево и вниз), а кислотные — к F (вправо и вверх по главной подгруппе) и с ростом степени окисления элемента.", "ref": "05.1"}, {"id": "p6", "t": "Водородные соединения (ЛВС): главный разворот тренда в группе", "x": "В отличие от высших кислородсодержащих кислот, кислотные свойства летучих водородных соединений неметаллов в группе сверху вниз УСИЛИВАЮТСЯ (HF < HCl < HBr < HI; H2O < H2S < H2Se), так как растёт радиус Э и ослабевает связь H—Э. Восстановительные свойства ЛВС растут влево и вниз, основность — влево и вверх, термическая устойчивость — вправо и вверх.", "ref": "06.1"}, {"id": "p7", "t": "Особые случаи: d-элементы, водород, инертные газы и уголок", "x": "Все d-элементы — металлы побочных подгрупп; в подгруппах благородных металлов активность сверху вниз падает (Cu > Ag > Au). Для сравнения трёх элементов не на одной прямой используется метод углового посредника: строим цепочку из двух однонаправленных стрелок через элемент на пересечении периода и группы.", "ref": "07.1"}, {"id": "p8", "t": "Боевой 4-шаговый алгоритм задания № 2 КИМ", "x": "В задании № 2 порядок трёх цифр строго важен (перестановка = 0 баллов). Всегда действуй по схеме: 1) фильтр 3 из 5 по таблице ФИПИ; 2) координаты / реальные формулы соединений; 3) выбор стрелки тренда (проверка: не ЛВС ли это?); 4) сверка направления («возрастание/усиление» vs «убывание/ослабление») перед записью ответа.", "ref": "08.1"}], "z": [{"id": "z1", "x": "Три перестановки по атомной массе (Ar 39,95 > K 39,10; Co 58,93 > Ni 58,69; Te 127,60 > I 126,90) доказывают, что Периодический закон определяется зарядом ядра Z, а не атомной массой.", "sk": "law_pshe", "ref": "01.5"}, {"id": "z2", "x": "Большой период (4–7-й) занимает в чёрно-белой таблице ФИПИ две строки: например, K (верхняя строка) и Br (нижняя строка) находятся в ОДНОМ 4-м периоде.", "sk": "law_pshe", "ref": "01.18"}, {"id": "z3", "x": "Гелий He (1s²) стоит в VIIIA группе, но относится к s-элементам (не к p-элементам!); Ga и Ge в 4-м периоде — это p-элементы, а не d-элементы.", "sk": "special_corner", "ref": "07.15"}, {"id": "z4", "x": "Катион всегда меньше своего нейтрального атома (Na^{+} < Na), а анион — больше (Cl^{−} > Cl). В изоэлектронном ряду (O^{2−}, F^{−}, Na^{+}, Mg^{2+}, Al^{3+}) радиус уменьшается с ростом заряда ядра Z.", "sk": "radius_ioniz", "ref": "02.16"}, {"id": "z5", "x": "Кислород O (3,44) электроотрицательнее хлора Cl (3,16) — он уступает по ЭО только фтору F (3,98). Благородные газы (He, Ne, Ar) не входят в ряды по ЭО и окислительной способности.", "sk": "electroneg", "ref": "03.13"}, {"id": "z6", "x": "Водород H (ЭО = 2,20) — неметалл и s-элемент: он электроотрицательнее всех металлов, Si (1,90) и B (2,04), поэтому в SiH4 у H степень окисления −1, а в CH4 (C = 2,55) — +1.", "sk": "electroneg", "ref": "03.9"}, {"id": "z7", "x": "В Задании № 2 для щелочных металлов всегда работает Периодический закон (Li < Na < K < Rb < Cs), а НЕ водный ряд напряжений, где Li стоит левее K из-за гидратации иона Li^{+}.", "sk": "metal_redox", "ref": "04.13"}, {"id": "z8", "x": "У фтора F (высшая СО = 0, валентность I) и кислорода O (высшая СО = +2 в OF2) нет высших оксидов и кислородсодержащих кислот; у азота N высшая СО = +5, но максимальная валентность равна IV.", "sk": "oxides_hydroxides", "ref": "05.16"}, {"id": "z9", "x": "Главный разворот ЕГЭ: кислотность высших кислородсодержащих кислот вниз по группе УБЫВАЕТ (HClO4 > HBrO4), а кислотность ЛВС вниз по группе УСИЛИВАЕТСЯ (HF < HCl < HBr < HI; H2O < H2S < H2Se).", "sk": "hydrides_lvs", "ref": "06.1"}, {"id": "z10", "x": "Низшая степень окисления неметаллов равна (№ группы − 8) и возрастает слева направо как алгебраическое число: −4 < −3 < −2 < −1 < 0; валентность в ЛВС (8 − № группы) убывает слева направо: IV → III → II → I.", "sk": "hydrides_lvs", "ref": "06.14"}, {"id": "z11", "x": "В побочных подгруппах благородных металлов (Cu → Ag → Au, Zn → Cd → Hg) восстановительная активность сверху вниз ПАДАЕТ (Cu > Ag > Au) из-за лантаноидного сжатия — противоположно главным подгруппам!", "sk": "special_corner", "ref": "07.4"}, {"id": "z12", "x": "По стандарту ФИПИ к щёлочноземельным металлам относят Ca, Sr, Ba, Ra (без Be и Mg), а к халькогенам — O, S, Se, Te (VIA); слова «в одной группе» объединяют А и Б, а «в одной главной подгруппе» — только А.", "sk": "kim2_algo", "ref": "08.4"}]}, "skills": [{"id": "law_pshe", "name": "Периодический закон и чтение таблицы ФИПИ", "ref": "01", "idea": "Понимать физический смысл Периодического закона и безошибочно отбирать элементы по периоду, группе, подгруппе А/Б и границе металлов/неметаллов в чёрно-белой таблице ФИПИ.", "pre": {"type": "one", "q": "Почему аргон (Z = 18, Ar = 39,95) стоит в Периодической системе раньше калия (Z = 19, Ar = 39,10), несмотря на большую атомную массу?", "o": ["Положение элемента и его свойства определяются зарядом ядра Z (числом протонов), а у Ar заряд +18 меньше, чем +19 у K", "У аргона больше электронных слоёв, чем у калия", "Калий является металлом, а все металлы ставят после неметаллов", "Аргон открыли раньше калия, поэтому оставили на 18-м месте"], "a": 0, "ex": "Современная формулировка Периодического закона связывает свойства элементов с зарядом атомных ядер Z (+18 у Ar < +19 у K), а не с атомной массой, зависящей от изотопного состава.", "d": {"1": "У аргона 3 электронных слоя (3-й период), а у калия — 4 слоя (4-й период).", "2": "Порядок элементов определяется строго ростом Z, независимо от принадлежности к металлам или неметаллам.", "3": "Историческая дата открытия никак не определяет место элемента в таблице."}}, "pair": {"type": "one", "cases": [["Фильтр: «три элемента в одной группе» для ряда K, Cr, Se, Br, O", "Выбираем Cr (VIБ), Se (VIA) и O (VIA) — все трое лежат в VI столбце таблицы"], ["Фильтр: «три элемента в одной главной подгруппе» для ряда O, S, Cr, Se, Cl", "Cr отпадает (побочная VIБ), остаются O, S, Se (главная VIA)"]], "q": "В чём ключевая разница между фильтрами «в одной группе» и «в одной главной подгруппе» в задании № 2 КИМ?", "o": ["«В одной группе» допускает элементы и А-, и Б-подгрупп одного столбца (например, O, Se и Cr), а «в одной главной подгруппе» — только элементы подгруппы А", "Эти две формулировки полностью эквивалентны", "«В одной группе» означает один горизонтальный ряд, а «в одной главной подгруппе» — вертикальный столбец", "«В одной главной подгруппе» включает только неметаллы"], "a": 0, "ex": "Вертикальный столбец (группа I–VIII) состоит из главной (А) и побочной (Б) подгрупп. В чёрно-белой таблице ФИПИ элементы А выровнены по элементам 2–3 периодов, а Б — по противоположному краю."}, "fade": {"q": "Восстанови ключевые правила чтения чёрно-белой таблицы ФИПИ:", "steps": ["Физическая причина периодического повторения свойств элементов — регулярное повторение строения {внешнего электронного слоя|ядра и числа нейтронов|кристаллической решётки} с ростом {заряда ядра Z|относительной атомной массы|температуры плавления}.", "В таблице ФИПИ 4-й период занимает {две строки|одну строку|три строки}, поэтому калий K и бром Br находятся в {одном 4-м периоде|разных периодах|одной группе}.", "Все элементы побочных подгрупп (Б) являются {металлами|неметаллами|благородными газами} и начинаются с {4-го|2-го|3-го} периода."]}, "bug": {"q": "Найди ошибочный шаг при первичном отборе трёх элементов одного периода из ряда: 1) K   2) O   3) Br   4) N   5) Se:", "steps": ["Выписываем периоды по таблице ФИПИ: O — 2-й период, N — 2-й период.", "K стоит в верхней строке 4-го периода (4-й ряд), а Se и Br — в нижней строке 4-го периода (5-й ряд).", "Так как K стоит в 4-й строке, а Se и Br — в 5-й строке, они лежат в разных периодах, поэтому трёх элементов одного периода в ряду нет.", "Правильный фильтр должен опираться на номер периода в левом столбце таблицы, а не на номер отдельной строки."], "bad": 2, "fix": "4-й период — большой и состоит из двух строк (4-го и 5-го рядов), поэтому K (1), Br (3) и Se (5) лежат в ОДНОМ 4-м периоде.", "why": "Путать номер ряда (строки) с номером большого периода — одна из самых частых ошибок на чёрно-белом бланке ФИПИ."}, "recall": {"q": "Назови по памяти 4 главных ориентира чёрно-белой таблицы ФИПИ для задания № 2.", "points": ["Номер периода = число электронных слоёв; большие периоды (4–7) занимают по две строки.", "Главная подгруппа (А) выровнена по тому же краю ячейки, что и элементы 2–3 периодов; побочная (Б) сдвинута к противоположному краю.", "Граница неметаллов — диагональ B–Si–As–Te–At (правее и выше + H = 22 неметалла; левее и ниже + все Б-подгруппы = металлы).", "Тривиальные семейства: щелочные (IA без H), щёлочноземельные (Ca, Sr, Ba, Ra без Be и Mg), халькогены (VIA), галогены (VIIA)."]}}, {"id": "radius_ioniz", "name": "Атомный радиус, ионы и энергия ионизации", "ref": "02", "idea": "Выводить изменение атомного радиуса, радиуса ионов и энергии ионизации из двух факторов — заряда ядра Z и числа электронных слоёв.", "pre": {"type": "one", "q": "Почему в пределах 2-го периода атомный радиус уменьшается от лития (Z = 3) к фтору (Z = 9), хотя число электронов увеличивается?", "o": ["Число электронных слоёв остаётся равным 2, а заряд ядра растёт от +3 до +9, сильнее стягивая электронную оболочку к центру", "У фтора на один электронный слой меньше, чем у лития", "Электроны у фтора имеют меньшую массу, чем у лития", "У лития действуют ядерные силы отталкивания между протонами и электронами"], "a": 0, "ex": "Внутри одного периода новые электроны поступают на тот же внешний уровень, а рост положительного заряда ядра усиливает кулоновское притяжение и сжимает атом.", "d": {"1": "И у Li, и у F ровно по 2 энергетических уровня (оба во 2-м периоде).", "2": "Все электроны имеют одинаковую массу.", "3": "Протоны (+) и электроны (−) всегда притягиваются, а не отталкиваются."}}, "pair": {"type": "one", "cases": [["Пара Na и Na^{+}", "При потере внешнего электрона 3s¹ исчезает целый 3-й слой → r(Na^{+}) < r(Na)"], ["Изоэлектронный ряд O^{2−}, F^{−}, Na^{+}, Mg^{2+}, Al^{3+}", "У всех по 10 электронов (1s²2s²2p⁶), но заряд ядра растёт от +8 до +13 → радиус убывает от O^{2−} к Al^{3+}"]], "q": "Какая частица в изоэлектронном ряду O^{2−}, F^{−}, Na^{+}, Mg^{2+}, Al^{3+} имеет НАИМЕНЬШИЙ радиус?", "o": ["Al^{3+} (наибольший заряд ядра +13 при тех же 10 электронах)", "O^{2−} (наименьший заряд ядра +8)", "Na^{+} (имеет минимальный положительный заряд +1)", "У всех пяти частиц одинаковый радиус, так как у них по 10 электронов"], "a": 0, "ex": "При одинаковой 10-электронной оболочке (1s²2s²2p⁶) сильнее всех стягивает электроны ядро с максимальным зарядом Z = +13 (Al^{3+}), а слабее всех — ядро кислорода (+8, O^{2−})."}, "fade": {"q": "Восстанови закономерности изменения атомного радиуса и энергии ионизации:", "steps": ["По периоду слева направо атомный радиус {уменьшается|увеличивается|не меняется}, а по главной подгруппе сверху вниз {увеличивается|уменьшается|остаётся постоянным}.", "Энергия ионизации меняется {противоположно|точно так же, как|независимо от} атомному радиусу: по периоду слева направо она {растёт|убывает}, а по группе сверху вниз {убывает|растёт}.", "Радиус катиона всегда {меньше|больше}, чем радиус его нейтрального атома, а радиус аниона всегда {больше|меньше}."]}, "bug": {"q": "Найди ошибочный шаг в решении задания Демоверсии ЕГЭ-2027 (ряд: 1) O  2) F  3) Al  4) Si  5) Li — выбрать три элемента одного периода и расположить по возрастанию атомного радиуса):", "steps": ["Определяем периоды: O (2), F (2), Al (3), Si (3), Li (2) → три элемента 2-го периода: O (1), F (2), Li (5).", "Во 2-м периоде заряд ядра растёт в ряду Li (+3) → O (+8) → F (+9).", "Поскольку у фтора больше всего электронов, его атомный радиус самый большой: Li < O < F.", "Записываем номера по возрастанию радиуса: 512."], "bad": 2, "fix": "Внутри одного периода при росте заряда ядра оболочка сжимается, поэтому радиус УБЫВАЕТ слева направо: F < O < Li. Правильный ответ по возрастанию — 215.", "why": "Капкан радиуса в периоде: рост числа электронов происходит на том же слое и не компенсирует рост заряда ядра."}, "recall": {"q": "Объясни по памяти 4 правила для радиуса атомов, ионов и энергии ионизации.", "points": ["Радиус растёт к Fr/Cs (справа налево по периоду и сверху вниз по главной подгруппе).", "Энергия ионизации растёт противоположно радиусу — вправо по периоду (максимум у благородных газов) и вверх по группе.", "r(катион) < r(атом) < r(анион); среди изоэлектронных ионов меньше тот, у кого больше Z.", "У d-элементов 4-го периода радиус меняется плавно (d-сжатие), а благородные газы не сравнивают с галогенами по ковалентному радиусу."]}}, {"id": "electroneg", "name": "Электроотрицательность и её подводные камни", "ref": "03", "idea": "Сравнивать электроотрицательность элементов в периодах, группах и уголках, помня точное место водорода H, пары O > Cl и исключение благородных газов.", "pre": {"type": "one", "q": "Какой химический элемент стоит на ВТОРОМ месте по электроотрицательности в Периодической системе (сразу после фтора F)?", "o": ["Кислород (O, ЭО = 3,44)", "Хлор (Cl, ЭО = 3,16)", "Азот (N, ЭО = 3,04)", "Неон (Ne, VIIIA группа)"], "a": 0, "ex": "По шкале Полинга тройка лидеров: F (3,98) > O (3,44) > Cl (3,16) ≈ N (3,04). У кислорода всего 2 электронных слоя, поэтому он притягивает электроны сильнее хлора (3 слоя).", "d": {"1": "Хлор стоит в VIIA, но в 3-м периоде (больше радиус) — его ЭО (3,16) меньше, чем у кислорода (3,44).", "2": "Азот лежит левее кислорода во 2-м периоде, поэтому ЭО(N) < ЭО(O).", "3": "Благородные газы имеют завершённый октет и на ЕГЭ не включаются в ряд ЭО."}}, "pair": {"type": "one", "cases": [["Метан CH4", "ЭО(C) = 2,55 > ЭО(H) = 2,20 → электроны смещены к углероду: C^{−4}H4^{+1}"], ["Силан SiH4", "ЭО(H) = 2,20 > ЭО(Si) = 1,90 → электроны смещены к водороду: Si^{+4}H4^{−1}"]], "q": "Почему в метане (CH4) водород имеет степень окисления +1, а в силане (SiH4) — степень окисления −1?", "o": ["По шкале ЭО водород (2,20) стоит между кремнием (1,90) и углеродом (2,55): он оттягивает электроны у Si, но отдаёт их C", "Кремний относится к металлам, а углерод — к неметаллам", "У силана ионная кристаллическая решётка, как у NaH", "В силане водород находится в возбуждённом состоянии"], "a": 0, "ex": "Ряд ЭО важнейших неметаллов: Si (1,90) < B (2,04) < P (2,19) ≈ H (2,20) < C (2,55) ≈ S (2,58) < I < Br < N < Cl < O < F."}, "fade": {"q": "Заполни ключевые правила сравнения электроотрицательности:", "steps": ["В периоде слева направо электроотрицательность {возрастает|убывает}, а в главной подгруппе сверху вниз {убывает|возрастает}.", "Абсолютный максимум ЭО принадлежит {фтору F|неону Ne|хлору Cl}, а благородные газы в ряд ЭО на ЕГЭ {не включают|ставят на первое место}.", "Водород H (2,20) более электроотрицателен, чем {Si и B|C и N|S и Cl}, но менее электроотрицателен, чем {C, N, O и галогены|щелочные металлы|Al и Mg}."]}, "bug": {"q": "Найди ошибочный шаг в сравнении ЭО элементов ряда: 1) O  2) Cl  3) S  4) Ne  5) Na (выбрать три неметалла, образующих соединения, и расположить по возрастанию ЭО):", "steps": ["Исключаем металл Na (5) и благородный газ Ne (4), так как инертные газы не сравнивают по ЭО.", "Остаются три неметалла: O (1), Cl (2), S (3).", "Сравниваем их положение: S и Cl в 3-м периоде (S < Cl), а Cl стоит в VIIA правее O (VIA), значит ЭО(Cl) > ЭО(O) → S < O < Cl.", "Записываем ответ по возрастанию: 312."], "bad": 2, "fix": "Кислород (2-й период, 3,44) всегда электроотрицательнее хлора (3-й период, 3,16), поэтому правильный ряд: S (2,58) < Cl (3,16) < O (3,44), ответ — 321.", "why": "Нельзя сравнивать O и Cl только по номеру группы: переход из 2-го периода в 3-й резко увеличивает радиус Cl и снижает его ЭО ниже O."}, "recall": {"q": "Назови по памяти 4 главных правила электроотрицательности для ЕГЭ.", "points": ["ЭО растёт к фтору F (вправо по периоду, вверх по главной подгруппе).", "Тройка лидеров: F (3,98) > O (3,44) > Cl (3,16) ≈ N (3,04) — кислород всегда сильнее хлора.", "Благородные газы (He, Ne, Ar) не входят в ряды по ЭО.", "Место водорода H (2,20): металлы < Si < B < P ≈ H < C ≈ S < I < Br < N < Cl < O < F."]}}, {"id": "metal_redox", "name": "Металлические, неметаллические и ОВ-свойства", "ref": "04", "idea": "Переводить термины «металлические / восстановительные» и «неметаллические / окислительные» в два противоположных вектора компаса и не подменять Периодический закон рядом напряжений.", "pre": {"type": "one", "q": "Как изменяются восстановительные свойства атомов в ряду щелочных металлов Li → Na → K → Rb → Cs по Периодическому закону (в задании № 2 ЕГЭ)?", "o": ["Усиливаются сверху вниз: Li < Na < K < Rb < Cs", "Ослабевают сверху вниз, потому что в ряду напряжений Li стоит левее K", "Сначала ослабевают от Li к Na, а затем усиливаются к Cs", "Не изменяются, так как у всех на внешнем уровне по 1 электрону"], "a": 0, "ex": "Сверху вниз по IA-подгруппе растёт число слоёв и атомный радиус, внешний электрон ns¹ всё слабее связан с ядром и легче отдаётся — металлические и восстановительные свойства строго растут: Li < Na < K < Rb < Cs.", "d": {"1": "Ряд напряжений отражает электродный потенциал в водном растворе (где огромна энергия гидратации малого иона Li^{+}), но в Задании № 2 проверяется Периодический закон!", "2": "Никакого разворота тренда в главной подгруппе щелочных металлов нет.", "3": "Хотя внешний электрон один, он находится на разном расстоянии от ядра (2s¹ vs 6s¹)."}}, "pair": {"type": "one", "cases": [["Металлические / восстановительные свойства", "Способность ОТДАВАТЬ электроны → растут при увеличении радиуса (к Fr/Cs: влево и вниз)"], ["Неметаллические / окислительные свойства", "Способность ПРИНИМАТЬ электроны → растут при уменьшении радиуса и росте ЭО (к F: вправо и вверх)"]], "q": "В каком ряду простые вещества расположены в порядке УСИЛЕНИЯ их окислительных свойств?", "o": ["I2 → Br2 → Cl2 → F2", "F2 → Cl2 → Br2 → I2", "Li → Na → K → Rb", "F2 → O2 → N2 → C"], "a": 0, "ex": "Окислительные свойства неметаллов усиливаются снизу вверх по группе (к фтору): I2 < Br2 < Cl2 < F2. Поэтому более активный галоген вытесняет менее активный из солей (Cl2 + 2KBr → 2KCl + Br2)."}, "fade": {"q": "Восстанови компас металлических, неметаллических и ОВ-свойств:", "steps": ["Способность атома отдавать электроны определяет его {металлические и восстановительные|неметаллические и окислительные} свойства; они усиливаются {справа налево|слева направо} по периоду и {сверху вниз|снизу вверх} по главной подгруппе.", "Способность атома принимать электроны определяет его {неметаллические и окислительные|металлические и восстановительные} свойства; они усиливаются к {фтору F|францию Fr|неону Ne}.", "Для щелочных металлов в задании № 2 всегда используется {Периодический закон (Li < Na < K)|водный ряд напряжений (Li > K)}."]}, "bug": {"q": "Найди ошибочный шаг в решении задачи: «Из ряда 1) Na  2) Mg  3) K  4) Li  5) Al выберите три элемента одной главной подгруппы и расположите по усилению восстановительных свойств»:", "steps": ["Находим три элемента одной главной подгруппы (IA): Na (1), K (3), Li (4).", "Вспоминаем, что восстановительные свойства металла совпадают с его металлическими свойствами.", "Смотрим в ряд напряжений металлов на бланке ЕГЭ: там Li стоит левее K, а K левее Na, значит по усилению: Na → K → Li.", "Записываем ответ: 134."], "bad": 2, "fix": "В задании № 2 нельзя подсматривать в водный ряд напряжений: по Периодическому закону в IA-подгруппе восстановительные свойства растут сверху вниз: Li < Na < K → правильный ответ 413.", "why": "Аномальное положение Li в ряду напряжений вызвано гидратацией иона Li^{+} в воде и не относится к периодическому изменению свойств атомов."}, "recall": {"q": "Назови по памяти 4 главных правила компаса ОВ-свойств и ловушки для № 2.", "points": ["Металлические = восстановительные (к Fr/Cs: влево и вниз); неметаллические = окислительные (к F: вправо и вверх).", "Ловушка № 1: в IA-подгруппе всегда Li < Na < K (Периодический закон, а не ряд напряжений!).", "Ловушка № 2: благородные газы (He, Ne, Ar) не входят в ряды по окислительной способности.", "Ловушка № 3: несмотря на инертность молекулы N2 при 20 °C, по Периодическому закону неметаллические и окислительные свойства атомов во 2-м периоде растут строго монотонно: C < N < O < F."]}}, {"id": "oxides_hydroxides", "name": "Высшие оксиды и высшие гидроксиды", "ref": "05", "idea": "Определять высший оксид и высший гидроксид элемента (включая кислородсодержащие кислоты неметаллов), выводить их кислотно-основные свойства и учитывать исключения F, O и N.", "pre": {"type": "one", "q": "Какое вещество является ВЫСШИМ ГИДРОКСИДОМ хлора (VIIA группа)?", "o": ["Хлорная кислота HClO4 (степень окисления Cl равна +7)", "Соляная кислота HCl (степень окисления Cl равна −1)", "Хлорноватистая кислота HClO (степень окисления Cl равна +1)", "Оксид хлора(VII) Cl2O7"], "a": 0, "ex": "Высший гидроксид — гидрат высшего оксида (Cl2O7 + H2O → 2HClO4), в котором элемент сохраняет высшую степень окисления (+7). Для неметаллов высшие гидроксиды — это кислородсодержащие кислоты!", "d": {"1": "HCl — это водородное соединение (бескислородная кислота), а не гидроксид.", "2": "В HClO степень окисления хлора +1, а не высшая (+7).", "3": "Cl2O7 — это высший оксид, а не гидроксид."}}, "pair": {"type": "one", "cases": [["Связь Na—O—H в NaOH", "У Na большой радиус и низкая ЭО → рвётся ионная связь Na | OH → в раствор уходит OH^{−} (щёлочь)"], ["Связь O3Cl—O—H в HClO4", "У Cl^{+7} малый радиус и высокая ЭО → стягивает электроны с O—H → рвётся связь O | H → уходит H^{+} (сильнейшая кислота)"]], "q": "Как меняются кислотные свойства высших гидроксидов в главной подгруппе сверху вниз (например, HNO3 → H3PO4 → H3AsO4)?", "o": ["Ослабевают: сверху вниз радиус центрального атома Э растёт, он слабее стягивает электроны со связи O—H, и протон H^{+} отрывается труднее", "Усиливаются, как у галогеноводородов HF < HCl < HBr", "Не изменяются, так как все элементы находятся в VA группе", "Сначала усиливаются от N к P, затем ослабевают к As"], "a": 0, "ex": "Кислотные свойства высших оксидов и высших гидроксидов подчиняются общему компасу к фтору F: усиливаются вправо по периоду и ВВЕРХ по главной подгруппе (значит, сверху вниз — ослабевают: HNO3 > H3PO4 > H3AsO4)."}, "fade": {"q": "Восстанови закономерности кислотно-основных свойств высших оксидов и гидроксидов:", "steps": ["В 3-м периоде от NaOH к HClO4 основные свойства высших гидроксидов {ослабевают|усиливаются}, а кислотные свойства {усиливаются|ослабевают}; промежуточный амфотерный гидроксид — {Al(OH)3|Mg(OH)2|H2SiO3}.", "В главной подгруппе сверху вниз основные свойства гидроксидов металлов {усиливаются|ослабевают}, а кислотные свойства высших гидроксидов неметаллов {ослабевают|усиливаются}.", "Для одного и того же элемента при росте степени окисления кислотные свойства оксида/гидроксида всегда {усиливаются|ослабевают}: CrO (+2) — {основный|кислотный}, Cr2O3 (+3) — {амфотерный|основный}, CrO3 (+6) — {кислотный|амфотерный}."]}, "bug": {"q": "Найди ошибочный шаг в рассуждении о высших степенях окисления и высших оксидах элементов 2-го периода (N, O, F):", "steps": ["У азота (VA) высшая степень окисления равна +5 (высший оксид N2O5, высший гидроксид HNO3), но максимальная валентность равна IV.", "У кислорода (VIA) высшая степень окисления равна +2 (в соединении OF2), поэтому оксидов с СО +6 у него нет.", "У фтора (VIIA) высший оксид имеет формулу F2O7, а высший гидроксид — HFO4, который является самой сильной кислотой.", "Следовательно, из тройки N, O, F по возрастанию высшей степени окисления ряд выглядит как F (0) < O (+2) < N (+5)."], "bad": 2, "fix": "У фтора нет положительных степеней окисления (высшая СО = 0 в F2), поэтому у фтора вообще не существует ни оксидов (OF2 — фторид кислорода), ни кислородсодержащих кислот.", "why": "F и O никогда не образуют высших оксидов с СО равной номеру группы; это один из самых частых капканов в задании № 2."}, "recall": {"q": "Назови по памяти 4 ключевых правила о высших оксидах и высших гидроксидах.", "points": ["Высший гидроксид неметалла — это его высшая кислородсодержащая кислота (H2CO3, HNO3, H2SiO3, H3PO4, H2SO4, HClO4).", "Кислотность высших оксидов и гидроксидов растёт к F (вправо и вверх по группе); основность растёт к Fr (влево и вниз).", "С ростом степени окисления одного элемента кислотность всегда растёт: CrO → Cr2O3 → CrO3; HClO < HClO2 < HClO3 < HClO4.", "У F и O нет высших оксидов/гидроксидов; у N высшая СО = +5, но высшая валентность = IV."]}}, {"id": "hydrides_lvs", "name": "Водородные соединения (ЛВС): разворот в группе", "ref": "06", "idea": "Уверенно различать гидриды металлов и ЛВС неметаллов, безошибочно применять разворот кислотности ЛВС в группе (HF < HCl < HBr < HI) и все 4 тренда ЛВС.", "pre": {"type": "one", "q": "Почему среди галогеноводородов HF является слабой кислотой, а HI — одной из сильнейших, хотя фтор намного электроотрицательнее иода?", "o": ["Сверху вниз по группе резко растёт радиус атома галогена, связь H—Hal удлиняется и ослабевает, поэтому протон H^{+} отрывается от HI намного легче, чем от HF", "У иода более высокая электроотрицательность, чем у фтора", "В молекуле HF нет полярной ковалентной связи", "HI является кислородсодержащей кислотой"], "a": 0, "ex": "В бескислородной кислоте H—Э водород связан напрямую с Э: сверху вниз определяющим становится рост радиуса Э (длина связи растёт, энергия связи падает, а в HF дополнительно мешают прочные водородные связи).", "d": {"1": "Фтор (3,98) значительно электроотрицательнее иода (2,66).", "2": "Связь H—F — самая полярная из всех H—Hal, но при этом самая короткая и прочная.", "3": "HI — бескислородная кислота (летучее водородное соединение)."}}, "pair": {"type": "one", "cases": [["Высшие гидроксиды (кислородсодержащие кислоты) в VIIA", "HClO4 > HBrO4 > H5IO6 — кислотность сверху вниз ОСЛАБЕВАЕТ"], ["Летучие водородные соединения (бескислородные кислоты) в VIIA", "HF < HCl < HBr < HI — кислотность сверху вниз УСИЛИВАЕТСЯ"]], "q": "Как изменяются в главной подгруппе сверху вниз (F → Cl → Br → I) кислотные свойства, восстановительные свойства и термическая устойчивость галогеноводородов?", "o": ["Кислотные и восстановительные свойства УСИЛИВАЮТСЯ, а термическая устойчивость ОСЛАБЕВАЕТ", "Все три свойства ослабевают сверху вниз", "Все три свойства усиливаются сверху вниз", "Кислотные свойства ослабевают, а восстановительные и устойчивость усиливаются"], "a": 0, "ex": "Из-за роста радиуса галогена вниз по группе связь H—Hal слабеет: легче отрывается H^{+} (кислотность растёт), легче разрушается молекула при нагреве (устойчивость падает), а крупный анион I^{−} легче отдаёт электроны (восстановительность растёт)."}, "fade": {"q": "Заполни сводные правила для летучих водородных соединений (ЛВС):", "steps": ["Летучие водородные соединения образуют неметаллы {IVA–VIIA|IA–IIA|побочных} групп; активные металлы IA–IIA групп образуют твёрдые ионные {гидриды с H^{−1}|летучие кислоты с H^{+1}}.", "Кислотность ЛВС усиливается {вправо|влево} по периоду и {вниз|вверх} по группе (H2O < H2S < H2Se; HF < HCl < HBr < HI).", "Валентность неметалла в ЛВС равна {8 − номер группы|номеру группы} и {убывает|возрастает} слева направо (CH4 IV → HF I), а низшая СО (№ группы − 8) {возрастает|убывает} слева направо (−4 < −3 < −2 < −1)."]}, "bug": {"q": "Найди ошибочный шаг в решении задачи: «Из ряда 1) S  2) O  3) Cl  4) Se  5) Na выберите три элемента одной главной подгруппы и расположите по ОСЛАБЛЕНИЮ кислотных свойств их водородных соединений»:", "steps": ["В одной главной подгруппе (VIA) находятся три элемента: S (1), O (2) и Se (4).", "Выписываем формулы их водородных соединений: H2O, H2S, H2Se.", "В VIA подгруппе сверху вниз неметаллические свойства убывают, значит кислотность водородных соединений тоже ослабевает: H2O > H2S > H2Se.", "В порядке ослабления получаем O → S → Se, ответ: 214."], "bad": 2, "fix": "Для водородных соединений (ЛВС) в группе работает главный разворот: сверху вниз кислотность УСИЛИВАЕТСЯ (H2O < H2S < H2Se), значит в порядке ослабления: Se → S → O → правильный ответ 412.", "why": "Автоматический перенос тренда высших кислородсодержащих кислот на водородные соединения — самая дорогая ловушка задания № 2."}, "recall": {"q": "Перечисли по памяти все 4 тренда ЛВС (в периоде и в группе) + формулы валентности и низшей СО.", "points": ["Кислотность ЛВС: усиливается вправо по периоду и ВНИЗ по группе (HF < HCl < HBr < HI; H2O < H2S < H2Se).", "Восстановительные свойства ЛВС: усиливаются влево по периоду (HCl < H2S < PH3) и ВНИЗ по группе (HF < HCl < HBr < HI).", "Основность ЛВС: ослабевает вправо (NH3 > H2O > HF) и вниз (NH3 > PH3 > AsH3); термическая устойчивость: растёт вправо и падает вниз (HF > HCl > HBr > HI).", "Валентность в ЛВС = 8 − № группы (убывает вправо: IV → I); низшая СО = № группы − 8 (возрастает вправо: −4 < −3 < −2 < −1)."]}}, {"id": "special_corner", "name": "d-элементы, особые группы и угловое сравнение", "ref": "07", "idea": "Безошибочно работать с d-элементами (в т.ч. Cu > Ag > Au), водородом, благородными газами, диагональными парами и сравнивать 3 элемента не на одной линии через углового посредника.", "pre": {"type": "one", "q": "Как изменяется химическая (восстановительная) активность простых веществ в побочной подгруппе IБ (Cu → Ag → Au) сверху вниз?", "o": ["Ослабевает (Cu > Ag > Au) — противоположно главной подгруппе щелочных металлов", "Усиливается (Cu < Ag < Au), так же как Li < Na < K", "Остаётся одинаковой, так как все три элемента имеют конфигурацию d¹⁰s¹", "Сначала усиливается от Cu к Ag, а затем падает к Au"], "a": 0, "ex": "В побочных подгруппах благородных металлов из-за лантаноидного сжатия заряд ядра резко возрастает при малом росте радиуса, поэтому внешние электроны удерживаются сильнее: Cu активнее Ag, а Ag активнее Au.", "d": {"1": "Правило усиления металлических свойств сверху вниз строго работает для главных подгрупп (А), но ломается в подгруппах Cu–Ag–Au и Zn–Cd–Hg.", "2": "Радиусы и эффективный заряд ядра у них существенно различаются.", "3": "Активность монотонно падает: Cu > Ag > Au."}}, "pair": {"type": "one", "cases": [["Уголок Al — Mg — Ca (радиус и основность)", "По 3-му периоду Al < Mg, по IIA-подгруппе Mg < Ca → обе стрелки в одну сторону: Al < Mg < Ca"], ["Уголок Si — C — N (ЭО и кислотность высших оксидов)", "По IVA-подгруппе Si < C, по 2-му периоду C < N → обе стрелки в одну сторону: Si < C < N"]], "q": "Как методом углового посредника сравнить электроотрицательность трёх p-элементов: P (3-й пер., VA), S (3-й пер., VIA) и O (2-й пер., VIA)?", "o": ["Использовать серу S как угловой элемент: по 3-му периоду P < S, а по VIA-подгруппе S < O → итого P < S < O", "Сначала сравнить P и O напрямую, а S поставить в конец ряда", "Элементы, не лежащие на одной линии, сравнить невозможно", "Взять порядок возрастания порядковых номеров Z: O (8) < P (15) < S (16)"], "a": 0, "ex": "Если три элемента образуют «уголок» (два в одном периоде и два в одной подгруппе), соединяем их через угловой элемент (здесь S): обе стрелки роста ЭО направлены одинаково (P → S → O)."}, "fade": {"q": "Заполни правила для особых групп и углового сравнения:", "steps": ["В 4-м периоде у d-элементов высшая степень окисления совпадает с номером группы только от {Sc (+3) до Mn (+7)|Sc (+3) до Zn (+2)|Fe (+6) до Cu (+2)}, а у цинка Zn она равна {+2|+12|+4}.", "Гелий He относится к {s-элементам|p-элементам}, а галлий Ga и германий Ge в 4-м периоде — к {p-элементам|d-элементам}.", "В диагональной паре {B и Si|N и O|Na и K} переход на новый период влияет сильнее сдвига на одну клетку вправо, поэтому атомный радиус {Si больше B|B больше Si}, а ЭО {B выше Si|Si выше B}."]}, "bug": {"q": "Найди ошибочный шаг в решении задачи: «Из ряда 1) B  2) Si  3) C  4) Ca  5) Fe выберите три p-элемента и расположите по УМЕНЬШЕНИЮ электроотрицательности»:", "steps": ["Исключаем Ca (s-элемент) и Fe (d-элемент); остаются три p-элемента: B (1), Si (2), C (3).", "Строим уголок через углерод C: по 2-му периоду B < C, по IVA-подгруппе Si < C → максимум ЭО у C.", "Сравниваем диагональную пару B (IIIA, 2-й пер.) и Si (IVA, 3-й пер.): поскольку Si стоит правее (в IV группе), его ЭО выше, чем у B → B < Si < C.", "В порядке уменьшения ЭО получаем C → Si → B, ответ: 321."], "bad": 2, "fix": "В диагональной паре B и Si добавление 3-го электронного слоя у Si снижает ЭО сильнее, чем сдвиг на 1 группу вправо: ЭО(Si) = 1,90 < ЭО(B) = 2,04 < ЭО(C) = 2,55. По уменьшению: C → B → Si → ответ 312.", "why": "При сравнении диагональных соседей 2-го и 3-го периодов (B–Si, C–P) обязательно проверяй влияние нового слоя и шкалу Полинга."}, "recall": {"q": "Назови по памяти 4 особых правила для d-элементов, H, He и углового сравнения.", "points": ["Все d-элементы — металлы Б-подгрупп; высшая СО равна номеру группы от Sc (+3) до Mn (+7), но не у Fe–Zn; в IБ и IIБ активность сверху вниз падает (Cu > Ag > Au).", "Водород H — s-элемент и неметалл (ЭО = 2,20); гелий He — s-элемент, а Ga, Ge, As, Se, Br — p-элементы 4-го периода.", "Диагональное сходство (Li–Mg, Be–Al, B–Si) возникает из-за частичной компенсации сжатия в периоде и расширения в группе.", "Метод углового посредника: ставим 3 элемента на сетку 2×2 и соединяем через угловой элемент цепочкой из двух однонаправленных стрелок."]}}, {"id": "kim2_algo", "name": "Алгоритм КИМ № 2: фильтры, критерии и порядок цифр", "ref": "08", "idea": "Безошибочно применять 4-шаговый алгоритм задания № 2 к любым комбинациям из 6 фильтров и 10 критериев, никогда не переворачивая «возрастание» и «убывание».", "pre": {"type": "one", "q": "Чем оценивание задания № 2 КИМ ЕГЭ по химии принципиально отличается от оценивания заданий № 1, 3 и 4?", "o": ["В задании № 2 порядок записи трёх цифр строго важен: любая перестановка даёт 0 баллов вместо 1", "В задании № 2 можно получить 2 первичных балла, а при одной ошибке — 1 балл", "В задании № 2 порядок цифр не важен, главное верно выбрать три элемента из пяти", "В задании № 2 всегда нужно выбрать 2 элемента из 5"], "a": 0, "ex": "Задание № 2 базового уровня даёт 1 первичный балл только при полном совпадении всех трёх цифр в строгой последовательности (например, 215 ≠ 512).", "d": {"1": "Максимальный балл за задание № 2 равен 1 (частичных баллов нет).", "2": "Это верно для № 1, 3 и 4, но строго неверно для № 2!", "3": "В задании № 2 всегда выбирают ровно 3 элемента из 5 и упорядочивают их."}}, "pair": {"type": "one", "cases": [["Ряд C, N, O — в порядке ВОЗРАСТАНИЯ валентности в ЛВС", "CH4 (IV), NH3 (III), H2O (II) → от меньшей к большей: O (II) → N (III) → C (IV)"], ["Ряд C, N, O — в порядке ВОЗРАСТАНИЯ низшей степени окисления", "C (−4), N (−3), O (−2) → по возрастанию алгебраического числа: C (−4) → N (−3) → O (−2)"]], "q": "Почему для одной и той же тройки C, N, O порядок «возрастания валентности в ЛВС» и порядок «возрастания низшей степени окисления» прямо противоположны?", "o": ["Валентность в ЛВС (8 − № группы) убывает слева направо (4 → 3 → 2), а отрицательная низшая СО (№ группы − 8) алгебраически растёт слева направо (−4 < −3 < −2)", "Углерод не образует летучего водородного соединения", "Низшая степень окисления сравнивается по модулю без учёта знака минус", "Валентность кислорода в воде равна VI"], "a": 0, "ex": "На числовой прямой −4 < −3 < −2 < −1 < 0 (возрастает слева направо), тогда как валентность в ЛВС (без знака) падает от IV у C до I у F."}, "fade": {"q": "Закрепи словарь-переключатель направления и контрольные точки алгоритма КИМ № 2:", "steps": ["Слова «возрастание», «увеличение», «усиление» всегда означают запись от {меньшего к большему|большего к меньшему}, а «убывание», «уменьшение», «ослабление» — от {большего к меньшему|меньшего к большему}.", "Если в условии встретилось слово «гидроксид» для неметаллов (P, S, Cl), пишем формулу {высшей кислородсодержащей кислоты (H3PO4, H2SO4, HClO4)|водородного соединения (PH3, H2S, HCl)}.", "Если в условии встретились слова «водородных соединений» для элементов одной группы, помним, что их кислотность растёт {сверху вниз|снизу вверх}."]}, "bug": {"q": "Найди ошибочный шаг в решении задачи: «Из ряда 1) Be  2) Mg  3) Ca  4) Ba  5) Sr выберите три ЩЁЛОЧНОЗЕМЕЛЬНЫХ металла и расположите по ослаблению основных свойств их гидроксидов»:", "steps": ["По стандарту ФИПИ к щёлочноземельным металлам относятся Ca (3), Ba (4) и Sr (5), а Be и Mg к ним не относят.", "В IIA подгруппе основные свойства гидроксидов усиливаются сверху вниз: Ca(OH)2 < Sr(OH)2 < Ba(OH)2.", "Нам нужен порядок ОСЛАБЛЕНИЯ (от самого сильного к самому слабому): Ba → Sr → Ca.", "Записываем номера в порядке Ba (4), Sr (5), Ca (3) — но поскольку в бланке ЕГЭ порядок цифр не важен, можно записать 345."], "bad": 3, "fix": "В задании № 2 порядок трёх цифр СТРОГО ВАЖЕН! Запись 345 вместо 453 даст 0 баллов.", "why": "Единственно верный ответ — строго 453 (от сильного основания Ba(OH)2 к более слабому Ca(OH)2)."}, "recall": {"q": "Назови по памяти 4 шага боевого алгоритма КИМ № 2 и 3 главные проверки перед записью ответа.", "points": ["Шаг 1: Отфильтруй ровно 3 элемента из 5, подписав над каждым период, подгруппу (А/Б) и семейство.", "Шаг 2: Выпиши реальные формулы соединений (высших гидроксидов или ЛВС), чтобы не спутать HClO4 и HCl.", "Шаг 3: Выбери правильный вектор тренда (к F, к Fr или особый разворот ЛВС вниз по группе).", "Шаг 4: Обведи слово-переключатель направления («возрастание/усиление» vs «убывание/ослабление») и переведи тройку символов в строгий порядок 3 цифр."]}}], "figs": {}, "tab": [{"id": "t_pshe_coords", "t": "Координаты элементов в чёрно-белой таблице ФИПИ", "k": "Элемент", "km": "элементом", "ref": "01.13", "n": 2, "lv3": ["Cr (хром)", "He (гелий)", "H (водород)", "Ga (галлий)", "Br (бром)"], "cols": [{"t": "Подгруппа (А / Б)", "sk": "law_pshe", "n": 2, "q": "В какой подгруппе (главной А или побочной Б) находится элемент {x} в таблице ФИПИ?", "m": "типом подгруппы", "mq": "Выберите {k} элемента, относящихся к «{v}»:"}, {"t": "Электронное семейство", "sk": "special_corner", "n": 2, "q": "К какому электронному семейству (s-, p- или d-элементов) относится {x}?", "m": "электронным семейством", "mq": "Выберите {k} элемента, относящихся к семейству «{v}»:"}, {"t": "Металл / неметалл", "sk": "law_pshe", "n": 2, "q": "К какой категории (металл или неметалл) относится элемент {x} в школьном курсе ЕГЭ?", "m": "принадлежностью к металлам или неметаллам", "mq": "Выберите {k} элемента категории «{v}»:"}], "rows": [["K (калий)", "Главная (А)", "s-элемент", "Металл"], ["Cr (хром)", "Побочная (Б)", "d-элемент", "Металл"], ["Mn (марганец)", "Побочная (Б)", "d-элемент", "Металл"], ["Zn (цинк)", "Побочная (Б)", "d-элемент", "Металл"], ["Ga (галлий)", "Главная (А)", "p-элемент", "Металл"], ["Se (селен)", "Главная (А)", "p-элемент", "Неметалл"], ["Br (бром)", "Главная (А)", "p-элемент", "Неметалл"], ["O (кислород)", "Главная (А)", "p-элемент", "Неметалл"], ["He (гелий)", "Главная (А)", "s-элемент", "Неметалл"], ["H (водород)", "Главная (А)", "s-элемент", "Неметалл"]], "rw": {"He (гелий)": "Ловушка! Стоит в VIIIA, но имеет конфигурацию 1s² → это s-элемент.", "Ga (галлий)": "Стоит в 4-м периоде после Zn, заполняется 4p¹ → p-элемент главной подгруппы IIIA.", "Cr (хром)": "Все элементы побочных подгрупп (Б) — d-элементы и исключительно металлы."}}, {"id": "t_higher_hydr", "t": "Высшие оксиды и высшие гидроксиды элементов 3-го периода", "k": "Элемент", "km": "элементом", "ref": "05.11", "n": 2, "lv3": ["Al (IIIA)", "Si (IVA)", "P (VA)", "S (VIA)", "Cl (VIIA)"], "cols": [{"t": "Высший гидроксид", "sk": "oxides_hydroxides", "n": 2, "q": "Какова формула ВЫСШЕГО ГИДРОКСИДА элемента {x}?", "m": "формулой высшего гидроксида"}, {"t": "Характер высшего гидроксида", "sk": "oxides_hydroxides", "n": 2, "q": "Какой кислотно-основный характер проявляет высший гидроксид элемента {x}?", "m": "характером высшего гидроксида", "mq": "Выберите {k} элемента, высшие гидроксиды которых имеют характер «{v}»:"}], "rows": [["Na (IA)", "NaOH", "Сильное основание (щёлочь)"], ["Mg (IIA)", "Mg(OH)2", "Слабое основание"], ["Al (IIIA)", "Al(OH)3", "Амфотерный гидроксид"], ["Si (IVA)", "H2SiO3", "Слабая кислота"], ["P (VA)", "H3PO4", "Кислота средней силы"], ["S (VIA)", "H2SO4", "Сильная кислота"], ["Cl (VIIA)", "HClO4", "Сильная кислота"]], "rw": {"S (VIA)": "Высший гидроксид серы — серная кислота H2SO4 (а не H2S!).", "Cl (VIIA)": "Высший гидроксид хлора — хлорная кислота HClO4 (+7), одна из сильнейших кислот."}}, {"id": "t_lvs_trends", "t": "Четыре свойства летучих водородных соединений (ЛВС) неметаллов", "k": "Свойство ЛВС", "km": "свойством ЛВС", "ref": "06.12", "n": 2, "lv3": ["Кислотные свойства ЛВС", "Восстановительные свойства ЛВС", "Термическая устойчивость ЛВС"], "cols": [{"t": "По периоду (слева → направо)", "sk": "hydrides_lvs", "n": 2, "q": "Как изменяются «{x}» в периоде слева направо (например, PH3 → H2S → HCl)?", "m": "изменением по периоду слева направо", "mq": "Выберите {k} свойства ЛВС, которые по периоду слева направо «{v}»:"}, {"t": "По группе (сверху → вниз)", "sk": "hydrides_lvs", "n": 2, "q": "Как изменяются «{x}» в главной подгруппе сверху вниз (например, HF → HCl → HBr → HI)?", "m": "изменением по группе сверху вниз", "mq": "Выберите {k} свойства ЛВС, которые по группе сверху вниз «{v}»:"}], "rows": [["Кислотные свойства ЛВС", "Усиливаются", "Усиливаются"], ["Основные свойства ЛВС", "Ослабевают", "Ослабевают"], ["Восстановительные свойства ЛВС", "Ослабевают", "Усиливаются"], ["Термическая устойчивость ЛВС", "Усиливается", "Ослабевает"]], "rw": {"Кислотные свойства ЛВС": "Главный разворот ЕГЭ: в группе сверху вниз кислотность ЛВС УСИЛИВАЕТСЯ (HF < HCl < HBr < HI).", "Восстановительные свойства ЛВС": "Растут влево (HCl < H2S < PH3) и вниз (HF < HCl < HBr < HI), так как крупный анион с низкой ЭО легче отдаёт e⁻."}}, {"id": "t_lvs_val_so", "t": "Валентность и низшая степень окисления неметаллов в ЛВС", "k": "Элемент", "km": "элементом", "ref": "06.14", "n": 2, "lv3": ["Si (кремний)", "C (углерод)", "N (азот)", "O (кислород)", "F (фтор)"], "cols": [{"t": "Валентность в ЛВС", "sk": "hydrides_lvs", "n": 2, "q": "Чему равна валентность элемента {x} в его летучем водородном соединении?", "m": "валентностью в ЛВС", "mq": "Выберите {k} элемента с валентностью в ЛВС «{v}»:"}, {"t": "Низшая степень окисления", "sk": "hydrides_lvs", "n": 2, "q": "Чему равна низшая (минимальная) степень окисления элемента {x}?", "m": "низшей степенью окисления", "mq": "Выберите {k} элемента с низшей степенью окисления «{v}»:"}], "rows": [["C (углерод)", "IV", "−4"], ["Si (кремний)", "IV", "−4"], ["N (азот)", "III", "−3"], ["P (фосфор)", "III", "−3"], ["O (кислород)", "II", "−2"], ["S (сера)", "II", "−2"], ["F (фтор)", "I", "−1"], ["Cl (хлор)", "I", "−1"]], "rw": {"Si (кремний)": "Осторожно: низшая СО кремния −4 (в силицидах Mg2Si), а в силане SiH4 у кремния +4, так как ЭО(H) > ЭО(Si)! Валентность в SiH4 равна IV."}}, {"id": "t_master_trends", "t": "Сводная карта всех периодических трендов (главные подгруппы)", "k": "Характеристика", "km": "характеристикой", "ref": "08.8", "n": 2, "lv3": ["Кислотные свойства высших гидроксидов", "Кислотные свойства ЛВС", "Восстановительные свойства ЛВС", "Низшая степень окисления неметаллов", "Валентность неметалла в ЛВС"], "cols": [{"t": "В периоде (слева → направо)", "sk": "kim2_algo", "n": 2, "q": "Как изменяется «{x}» в периоде слева направо?", "m": "трендом по периоду слева направо", "mq": "Выберите {k} характеристики, которые по периоду слева направо «{v}»:"}, {"t": "В главной подгруппе (сверху → вниз)", "sk": "kim2_algo", "n": 2, "q": "Как изменяется «{x}» в главной подгруппе сверху вниз?", "m": "трендом по главной подгруппе сверху вниз", "mq": "Выберите {k} характеристики, которые по главной подгруппе сверху вниз «{v}»:"}], "rows": [["Атомный радиус", "Убывает", "Возрастает"], ["Энергия ионизации", "Возрастает", "Убывает"], ["Электроотрицательность (ЭО)", "Возрастает", "Убывает"], ["Металлические и восстановительные свойства", "Ослабевают", "Усиливаются"], ["Неметаллические и окислительные свойства", "Усиливаются", "Ослабевают"], ["Основные свойства высших оксидов и гидроксидов", "Ослабевают", "Усиливаются"], ["Кислотные свойства высших гидроксидов", "Усиливаются", "Ослабевают"], ["Кислотные свойства ЛВС", "Усиливаются", "Усиливаются"], ["Восстановительные свойства ЛВС", "Ослабевают", "Усиливаются"], ["Низшая степень окисления неметаллов", "Возрастает", "Постоянна"], ["Валентность неметалла в ЛВС", "Убывает", "Постоянна"]], "rw": {"Кислотные свойства ЛВС": "Единственное свойство, которое усиливается и вправо по периоду, и ВНИЗ по группе!"}}], "rx": [], "seq": [{"id": "sq_radius_2p", "sk": "radius_ioniz", "ref": "02.6", "n": 2, "lvl": 2, "q": "Расположите элементы 2-го периода в порядке ВОЗРАСТАНИЯ их атомных радиусов (от самого маленького к самому большому):", "items": ["F (Z = +9, наименьший радиус)", "O (Z = +8)", "N (Z = +7)", "C (Z = +6)", "Li (Z = +3, наибольший радиус во 2-м периоде)"], "why": "В одном периоде число слоёв одинаково (2 слоя), а при уменьшении заряда ядра от +9 к +3 оболочка сжимается слабее — радиус растёт справа налево: F < O < N < C < Li."}, {"id": "sq_isoelec_ions", "sk": "radius_ioniz", "ref": "02.16", "n": 2, "lvl": 3, "q": "Расположите изоэлектронные ионы (у всех по 10 электронов) в порядке УМЕНЬШЕНИЯ их радиуса (от самого крупного к самому маленькому):", "items": ["O^{2−} (Z = +8)", "F^{−} (Z = +9)", "Na^{+} (Z = +11)", "Mg^{2+} (Z = +12)", "Al^{3+} (Z = +13)"], "why": "При одинаковом числе электронов (10) радиус строго убывает с ростом заряда ядра Z: O^{2−} > F^{−} > Na^{+} > Mg^{2+} > Al^{3+}."}, {"id": "sq_eo_nonmetals", "sk": "electroneg", "ref": "03.6", "n": 2, "lvl": 3, "q": "Расположите неметаллы (включая водород) в порядке ВОЗРАСТАНИЯ их электроотрицательности по шкале Полинга:", "items": ["Si (1,90)", "B (2,04)", "H (2,20)", "C (2,55)", "N (3,04)", "O (3,44)", "F (3,98)"], "why": "Запомни опорное положение водорода: Si < B < H < C < N < O < F."}, {"id": "sq_alkali_redox", "sk": "metal_redox", "ref": "04.8", "n": 2, "lvl": 2, "q": "Расположите щелочные металлы в порядке УСИЛЕНИЯ их восстановительных свойств по Периодическому закону (для задания № 2):", "items": ["Li (2 слоя)", "Na (3 слоя)", "K (4 слоя)", "Rb (5 слоёв)", "Cs (6 слоёв)"], "why": "В IA-подгруппе сверху вниз растёт радиус атома и легче отдаётся внешний электрон ns¹: Li < Na < K < Rb < Cs (не путать с водным рядом напряжений!)."}, {"id": "sq_3p_hydroxides", "sk": "oxides_hydroxides", "ref": "05.11", "n": 2, "lvl": 2, "q": "Расположите высшие гидроксиды элементов 3-го периода в порядке УСИЛЕНИЯ кислотных (ослабления основных) свойств:", "items": ["NaOH (щёлочь)", "Mg(OH)2 (слабое основание)", "Al(OH)3 (амфотерный гидроксид)", "H2SiO3 (слабая кислота)", "H3PO4 (кислота средней силы)", "H2SO4 (сильная кислота)", "HClO4 (одна из сильнейших кислот)"], "why": "Слева направо по периоду растёт ЭО и высшая степень окисления элемента, связь O—H ослабевает — свойства плавно переходят от щёлочи к сильнейшей кислоте."}, {"id": "sq_lvs_acid_group", "sk": "hydrides_lvs", "ref": "06.8", "n": 2, "lvl": 3, "q": "Расположите галогеноводороды в порядке УСИЛЕНИЯ их кислотных свойств в водном растворе:", "items": ["HF (слабая кислота)", "HCl (сильная кислота)", "HBr (ещё сильнее)", "HI (сильнейшая из галогеноводородных)"], "why": "Главный разворот в группе: сверху вниз радиус галогена растёт, связь H—Hal удлиняется и легче отщепляет протон H^{+} (HF < HCl < HBr < HI)."}, {"id": "sq_lvs_stab_group", "sk": "hydrides_lvs", "ref": "06.12", "n": 2, "lvl": 3, "q": "Расположите галогеноводороды в порядке ОСЛАБЛЕНИЯ их термической устойчивости (от самого прочного к самому неустойчивому):", "items": ["HF (самая короткая и прочная связь H—F)", "HCl", "HBr", "HI (легче всех разлагается при нагревании)"], "why": "Сверху вниз длина связи H—Hal увеличивается, её энергия падает, поэтому термическая устойчивость убывает: HF > HCl > HBr > HI."}, {"id": "sq_kim2_algo", "sk": "kim2_algo", "ref": "08.1", "n": 2, "lvl": 2, "q": "Установите правильную последовательность шагов боевого алгоритма решения задания № 2 КИМ ЕГЭ-2027:", "items": ["Подписать над всеми пятью элементами их период, подгруппу (А/Б) и семейство и отфильтровать ровно 3 элемента", "Выписать координаты тройки (или реальные формулы высших гидроксидов / ЛВС)", "Выбрать правильный вектор тренда (к F, к Fr или особый разворот ЛВС вниз по группе)", "Сверить слово-переключатель направления («возрастание/усиление» vs «убывание/ослабление») и записать 3 цифры строго в нужном порядке"], "why": "Пошаговая проверка защищает одновременно от ошибок в фильтре 3 из 5, подмены HClO4 на HCl и случайного переворота ответа."}], "facts": [{"id": "f_pshe_rules", "sk": "law_pshe", "ref": "01.18", "n": 2, "lvl": 2, "t": "Периодический закон и чтение таблицы ФИПИ", "s": [["Аргон (Z = 18) стоит раньше калия (Z = 19), так как порядок элементов определяется зарядом ядра, а не атомной массой.", "Аргон стоит раньше калия, потому что его относительная атомная масса меньше, чем у калия.", "Ar(Ar) = 39,95 > Ar(K) = 39,10, но заряд ядра +18 меньше, чем +19."], ["Калий K и бром Br находятся в одном (4-м) периоде таблицы Менделеева.", "Калий K и бром Br находятся в разных периодах, так как стоят в разных строках чёрно-белой таблицы ФИПИ.", "4-й период — большой и состоит из двух строк (4-го и 5-го рядов), но это один период."], ["Элементы побочных подгрупп (Б) начинаются с 4-го периода и все без исключения являются металлами.", "Среди элементов побочных подгрупп (Б) встречаются как металлы, так и неметаллы.", "Абсолютно все d- и f-элементы побочных подгрупп — металлы."], ["Формулировка «в одной группе» объединяет элементы А- и Б-подгрупп одного столбца (например, O, Se и Cr).", "Формулировки «в одной группе» и «в одной главной подгруппе» полностью совпадают.", "«В одной группе» допускает побочную подгруппу, а «в одной главной подгруппе» — только элементы А."], ["По стандарту ФИПИ к щёлочноземельным металлам относят Ca, Sr, Ba, Ra, не включая Be и Mg.", "К щёлочноземельным металлам на ЕГЭ обязательно относят бериллий Be и магний Mg.", "Оксиды Be и Mg не образуют щелочей с водой (BeO амфотерен, Mg(OH)2 малорастворим), поэтому в ФИПИ щёлочноземельные — Ca, Sr, Ba, Ra."]]}, {"id": "f_radius_eo", "sk": "electroneg", "ref": "03.9", "n": 2, "lvl": 3, "t": "Атомный радиус, ионы и электроотрицательность", "s": [["В пределах одного периода слева направо атомный радиус уменьшается из-за роста заряда ядра при неизменном числе электронных слоёв.", "В пределах одного периода слева направо атомный радиус увеличивается из-за роста числа электронов.", "Новые электроны идут на тот же слой, а ядро сильнее стягивает оболочку → радиус убывает."], ["Радиус катиона Na^{+} меньше радиуса нейтрального атома Na, а радиус аниона Cl^{−} больше радиуса атома Cl.", "Радиус катиона всегда больше радиуса его нейтрального атома.", "Отдача электрона уменьшает отталкивание (и убирает внешний слой у Na^{+}), поэтому катион всегда меньше атома."], ["Кислород O электроотрицательнее хлора Cl и уступает по ЭО только фтору F.", "Хлор Cl электроотрицательнее кислорода O, так как стоит в VIIA группе правее кислорода.", "По шкале Полинга ЭО(O) = 3,44 > ЭО(Cl) = 3,16, поскольку у O на один электронный слой меньше."], ["Благородные газы (He, Ne, Ar) не включаются в ряды сравнения по электроотрицательности и окислительной способности на ЕГЭ.", "Неон Ne обладает более высокой электроотрицательностью, чем фтор F, так как стоит правее во 2-м периоде.", "У благородных газов завершённый внешний слой; чемпион по ЭО — фтор F."], ["Водород H более электроотрицателен, чем кремний Si и бор B, но менее электроотрицателен, чем углерод C и сера S.", "Поскольку водород стоит в IA группе, его электроотрицательность меньше, чем у всех p-элементов, включая кремний.", "ЭО(H) = 2,20 > ЭО(Si) = 1,90 и ЭО(B) = 2,04, но < ЭО(C) = 2,55 и ЭО(S) = 2,58."]]}, {"id": "f_metal_ox", "sk": "metal_redox", "ref": "04.13", "n": 2, "lvl": 3, "t": "Металлические, ОВ-свойства и высшие гидроксиды", "s": [["В задании № 2 восстановительные свойства щелочных металлов усиливаются сверху вниз: Li < Na < K < Rb < Cs.", "В задании № 2 литий является более сильным восстановителем, чем калий, как в электрохимическом ряду напряжений.", "Ряд напряжений отражает потенциал в воде (гидратация Li^{+}), а в № 2 проверяется Периодический закон."], ["Высшими гидроксидами неметаллов называют их высшие кислородсодержащие кислоты (HNO3, H3PO4, H2SO4, HClO4).", "Слово «гидроксид» в заданиях ЕГЭ относится только к основаниям и амфотерным гидроксидам металлов.", "Кислородсодержащие кислоты — это гидраты высших кислотных оксидов, то есть высшие гидроксиды неметаллов."], ["Кислотные свойства высших оксидов и высших гидроксидов в главной подгруппе сверху вниз ослабевают (HNO3 > H3PO4 > H3AsO4).", "Кислотные свойства высших кислородсодержащих кислот в главной подгруппе сверху вниз усиливаются (HClO4 < HBrO4).", "Сверху вниз растёт радиус центрального атома, он хуже поляризует связь O—H → кислотность высших кислот падает."], ["У фтора F нет оксидов и кислородсодержащих кислот, а вещество OF2 является фторидом кислорода(II).", "Фтор образует высший оксид F2O7 и сильнейшую кислоту HFO4.", "Фтор — самый электроотрицательный элемент; он не бывает в положительной степени окисления."], ["У азота N высшая степень окисления равна +5 (в HNO3), но высшая валентность равна IV.", "У азота и высшая степень окисления (+5), и высшая валентность (V) совпадают с номером группы.", "На 2-м уровне у азота нет 2d-орбиталей (всего 4 орбитали: 2s и три 2p), поэтому максимальная валентность N равна IV."]]}, {"id": "f_lvs_traps", "sk": "hydrides_lvs", "ref": "06.20", "n": 2, "lvl": 3, "t": "Ловушки летучих водородных соединений (ЛВС)", "s": [["В главной подгруппе сверху вниз кислотные свойства летучих водородных соединений усиливаются (HF < HCl < HBr < HI; H2O < H2S < H2Se).", "В главной подгруппе сверху вниз кислотные свойства водородных соединений ослабевают (HF > HCl > HBr > HI).", "Рост радиуса атома Э ослабляет прямую связь H—Э, поэтому протон H^{+} отрывается всё легче."], ["Восстановительные свойства ЛВС усиливаются справа налево по периоду (HCl < H2S < PH3) и сверху вниз по группе (HF < HCl < HBr < HI).", "Восстановительные свойства ЛВС усиливаются слева направо по периоду (PH3 < H2S < HCl).", "Чем ниже ЭО и крупнее атом Э, тем легче частица в низшей СО отдаёт электроны."], ["Термическая устойчивость галогеноводородов сверху вниз ослабевает: HF > HCl > HBr > HI.", "Поскольку HI — самая сильная кислота, молекула HI обладает наибольшей термической устойчивостью.", "Сильная кислотность HI и его низкая термическая устойчивость имеют одну причину — слабую длинную связь H—I."], ["Основные свойства водородных соединений ослабевают сверху вниз (NH3 > PH3 > AsH3) и слева направо (NH3 > H2O > HF).", "Фосфин PH3 проявляет более сильные основные свойства, чем аммиак NH3.", "У азота неподелённая пара на компактном 2p-уровне намного эффективнее присоединяет протон H^{+}."], ["В периоде слева направо низшая степень окисления неметаллов возрастает (−4 < −3 < −2 < −1), а валентность в ЛВС убывает (IV → III → II → I).", "В периоде слева направо валентность неметаллов в ЛВС возрастает от I до IV.", "Валентность в ЛВС равна (8 − номер группы): CH4 (IV) → NH3 (III) → H2O (II) → HF (I)."]]}, {"id": "f_special_d", "sk": "special_corner", "ref": "07.14", "n": 2, "lvl": 3, "t": "d-элементы, водород, гелий и диагональные пары", "s": [["В побочной подгруппе IБ восстановительная активность металлов сверху вниз падает: Cu > Ag > Au.", "В побочной подгруппе IБ восстановительная активность металлов сверху вниз растёт: Cu < Ag < Au.", "Из-за лантаноидного сжатия внешние электроны у Ag и Au удерживаются сильнее, чем у Cu."], ["Гелий He (1s²) является s-элементом, а галлий Ga и германий Ge в 4-м периоде — p-элементами.", "Гелий He относится к p-элементам, а галлий Ga — к d-элементам.", "Семейство определяется последним заполняемым подуровнем: 1s² у He (s) и 4p¹/4p² у Ga/Ge (p)."], ["Среди d-элементов 4-го периода высшая степень окисления совпадает с номером группы от Sc (+3) до Mn (+7), но не у Fe, Co, Ni, Cu, Zn.", "У всех d-элементов 4-го периода высшая степень окисления равна номеру группы (у Fe +8, у Zn +2).", "У железа в соединениях максимум +6 (ферраты), у меди +2, а +8 железо не проявляет."], ["Диагональное сходство пар Be–Al и Li–Mg объясняется взаимной компенсацией сжатия по периоду и расширения по группе.", "Бериллий и алюминий сходны только потому, что находятся в одном периоде.", "Be (2-й пер., IIA) и Al (3-й пер., IIIA) сдвинуты по диагонали на 1 клетку вправо и вниз."], ["В диагональной паре B и Si электроотрицательность бора (2,04) выше, чем у кремния (1,90), а атомный радиус кремния больше, чем у бора.", "В диагональной паре B и Si кремний электроотрицательнее бора, так как стоит в IVA группе.", "Добавление нового (3-го) электронного слоя у Si влияет сильнее, чем сдвиг на 1 группу вправо."]]}], "calc": [{"id": "c_lvs_valence", "sk": "hydrides_lvs", "ref": "06.14", "n": 2, "lvl": 1, "v": {"_": [{"el": "углерода (C, IVA)", "G": 4}, {"el": "кремния (Si, IVA)", "G": 4}, {"el": "азота (N, VA)", "G": 5}, {"el": "фосфора (P, VA)", "G": 5}, {"el": "кислорода (O, VIA)", "G": 6}, {"el": "серы (S, VIA)", "G": 6}, {"el": "фтора (F, VIIA)", "G": 7}, {"el": "хлора (Cl, VIIA)", "G": 7}]}, "q": "Чему равна валентность атома {=el} в его летучем водородном соединении (числом)?", "a": "8 - G", "dp": 0, "unit": "", "ex": "Валентность неметалла IVA–VIIA групп в ЛВС равна 8 − номер группы = 8 − {=G} = {=8-G}."}, {"id": "c_max_so_main", "sk": "oxides_hydroxides", "ref": "05.3", "n": 2, "lvl": 1, "v": {"_": [{"el": "натрия (Na, IA)", "G": 1}, {"el": "магния (Mg, IIA)", "G": 2}, {"el": "алюминия (Al, IIIA)", "G": 3}, {"el": "кремния (Si, IVA)", "G": 4}, {"el": "фосфора (P, VA)", "G": 5}, {"el": "серы (S, VIA)", "G": 6}, {"el": "хлора (Cl, VIIA)", "G": 7}, {"el": "марганца (Mn, VIIБ)", "G": 7}]}, "q": "Чему равна высшая положительная степень окисления элемента {=el} (введите число без знака +)?", "a": "G", "dp": 0, "unit": "", "ex": "Для данного элемента (не относящегося к исключениям F, O, инертным газам и Fe–Cu) высшая степень окисления равна номеру группы: +{=G}."}], "tasks": [{"id": "t01_demo2027", "type": "short", "sk": "radius_ioniz", "ref": "02.12", "n": 2, "lvl": 2, "q": "[ДЕМО-2027 ФИПИ] Из указанных в ряду элементов:\n1) O   2) F   3) Al   4) Si   5) Li\nвыберите три элемента, которые в Периодической системе находятся в одном периоде. Расположите выбранные элементы в порядке ВОЗРАСТАНИЯ их атомных радиусов. Запишите номера элементов в нужной последовательности (3 цифры без пробелов).", "a": "215", "ex": "В одном (2-м) периоде находятся O (1), F (2) и Li (5). По периоду справа налево радиус растёт (заряд ядра убывает от +9 к +3): F < O < Li. В порядке возрастания: 215."}, {"id": "t02_big_period_4", "type": "short", "sk": "law_pshe", "ref": "01.18", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) K   2) O   3) Br   4) N   5) Se\nвыберите три элемента, которые находятся в одном периоде. Расположите выбранные элементы в порядке УМЕНЬШЕНИЯ их атомных радиусов. Запишите 3 цифры без пробелов.", "a": "153", "ex": "Ловушка большого периода из 2 строк! В 4-м периоде лежат K (1, верхняя строка), Se (5, нижняя строка) и Br (3, нижняя строка). Слева направо по 4-му периоду радиус уменьшается: K > Se > Br → ответ: 153."}, {"id": "t03_ionization_group", "type": "short", "sk": "radius_ioniz", "ref": "02.9", "n": 2, "lvl": 2, "q": "Из указанных в ряду элементов:\n1) Be   2) Mg   3) Na   4) Ca   5) Al\nвыберите три элемента, которые находятся в одной главной подгруппе. Расположите выбранные элементы в порядке ВОЗРАСТАНИЯ их энергии ионизации. Запишите 3 цифры без пробелов.", "a": "421", "ex": "В IIA подгруппе лежат Be (1), Mg (2), Ca (4). Энергия ионизации меняется противоположно радиусу — растёт снизу вверх по группе: Ca < Mg < Be → ответ: 421."}, {"id": "t04_group_vs_subgroup", "type": "short", "sk": "law_pshe", "ref": "01.17", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) O   2) Cr   3) N   4) Se   5) K\nвыберите три элемента, которые находятся в ОДНОЙ ГРУППЕ Периодической системы. Расположите выбранные элементы в порядке ВОЗРАСТАНИЯ их атомных радиусов. Запишите 3 цифры без пробелов.", "a": "142", "ex": "В VI группе (включая А и Б!) стоят O (1, 2-й пер., VIA), Se (4, 4-й пер., VIA) и Cr (2, 4-й пер., VIБ). У O 2 слоя (самый маленький); Se и Cr оба в 4-м периоде, но Cr стоит левее Se (меньше заряд ядра), значит r(Cr) > r(Se). Итого: O < Se < Cr → ответ: 142."}, {"id": "t05_eo_corner_pso", "type": "short", "sk": "electroneg", "ref": "03.11", "n": 2, "lvl": 2, "q": "Из указанных в ряду элементов:\n1) P   2) S   3) O   4) Al   5) Mg\nвыберите три неметалла. Расположите выбранные элементы в порядке ВОЗРАСТАНИЯ их электроотрицательности. Запишите 3 цифры без пробелов.", "a": "123", "ex": "Неметаллы: P (1), S (2), O (3). Строим уголок через S: по 3-му периоду P < S, по VIA-подгруппе S < O → P < S < O. По возрастанию: 123."}, {"id": "t06_eo_o_vs_cl", "type": "short", "sk": "electroneg", "ref": "03.13", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) Cl   2) S   3) O   4) Ne   5) Na\nвыберите три элемента, образующих летучие водородные соединения, и расположите их в порядке УМЕНЬШЕНИЯ электроотрицательности. Запишите 3 цифры без пробелов.", "a": "312", "ex": "Ne (благородный газ) и Na (металл, образует твёрдый гидрид NaH) не образуют ЛВС. Остаются Cl (1), S (2) и O (3). Главная ловушка: кислород (2-й период, ЭО = 3,44) электроотрицательнее хлора (3-й период, ЭО = 3,16), а хлор электроотрицательнее серы (2,58): O > Cl > S → ответ: 312."}, {"id": "t07_eo_hydrogen", "type": "short", "sk": "electroneg", "ref": "03.9", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) Si   2) H   3) C   4) Na   5) Ca\nвыберите три неметалла. Расположите выбранные элементы в порядке ВОЗРАСТАНИЯ их электроотрицательности. Запишите 3 цифры без пробелов.", "a": "123", "ex": "Неметаллы: Si (1), H (2), C (3). По шкале Полинга водород (2,20) стоит между кремнием (1,90) и углеродом (2,55): Si < H < C → ответ: 123."}, {"id": "t08_redox_period3", "type": "short", "sk": "metal_redox", "ref": "04.10", "n": 2, "lvl": 2, "q": "Из указанных в ряду элементов:\n1) Na   2) Mg   3) K   4) Ca   5) Al\nвыберите три элемента, которые находятся в одном периоде. Расположите выбранные элементы в порядке УСИЛЕНИЯ восстановительных свойств соответствующих им простых веществ. Запишите 3 цифры без пробелов.", "a": "521", "ex": "В 3-м периоде лежат Na (1), Mg (2), Al (5). Восстановительные (= металлические) свойства растут справа налево (к Fr): Al < Mg < Na. По усилению: 521."}, {"id": "t09_alkali_trap", "type": "short", "sk": "metal_redox", "ref": "04.13", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) Na   2) Mg   3) K   4) Li   5) Ca\nвыберите три элемента одной главной подгруппы. Расположите выбранные элементы в порядке УСИЛЕНИЯ металлических (восстановительных) свойств. Запишите 3 цифры без пробелов.", "a": "413", "ex": "В IA-подгруппе лежат Na (1), K (3), Li (4). Ловушка ряда напряжений! В задании № 2 работает строго Периодический закон: сверху вниз радиус растёт, восстановительные свойства усиливаются — Li < Na < K → ответ: 413."}, {"id": "t10_oxidizing_halogens", "type": "short", "sk": "metal_redox", "ref": "04.8", "n": 2, "lvl": 2, "q": "Из указанных в ряду элементов:\n1) Cl   2) Br   3) S   4) F   5) Ar\nвыберите три элемента, относящихся к галогенам. Расположите выбранные элементы в порядке ОСЛАБЛЕНИЯ окислительных свойств соответствующих им простых веществ. Запишите 3 цифры без пробелов.", "a": "412", "ex": "Галогены (VIIA): Cl (1), Br (2), F (4). Окислительные свойства ослабевают сверху вниз по группе: F2 > Cl2 > Br2 → ответ: 412."}, {"id": "t11_higher_hydr_va", "type": "short", "sk": "oxides_hydroxides", "ref": "05.14", "n": 2, "lvl": 2, "q": "Из указанных в ряду элементов:\n1) P   2) N   3) As   4) F   5) O\nвыберите три элемента, которые находятся в одной главной подгруппе. Расположите выбранные элементы в порядке УСИЛЕНИЯ кислотных свойств их высших гидроксидов. Запишите 3 цифры без пробелов.", "a": "312", "ex": "В VA-подгруппе лежат P (1), N (2), As (3). Их высшие гидроксиды — H3AsO4, H3PO4, HNO3. Кислотность высших кислородсодержащих кислот растёт снизу вверх: H3AsO4 < H3PO4 < HNO3 → ответ: 312."}, {"id": "t12_higher_hydr_3p", "type": "short", "sk": "oxides_hydroxides", "ref": "05.11", "n": 2, "lvl": 2, "q": "Из указанных в ряду элементов:\n1) P   2) Si   3) S   4) Mg   5) Ca\nвыберите три p-элемента. Расположите выбранные элементы в порядке УСИЛЕНИЯ кислотных свойств их высших гидроксидов. Запишите 3 цифры без пробелов.", "a": "213", "ex": "p-элементы (3-й период): P (1), Si (2), S (3). Их высшие гидроксиды — H2SiO3, H3PO4, H2SO4. Слева направо кислотность усиливается: Si < P < S → ответ: 213."}, {"id": "t13_alkaline_earth_basic", "type": "short", "sk": "oxides_hydroxides", "ref": "05.12", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) Be   2) Ca   3) Mg   4) Ba   5) Sr\nвыберите три ЩЁЛОЧНОЗЕМЕЛЬНЫХ металла (по стандарту ФИПИ). Расположите выбранные элементы в порядке ОСЛАБЛЕНИЯ основных свойств их высших гидроксидов. Запишите 3 цифры без пробелов.", "a": "452", "ex": "По стандарту ФИПИ щёлочноземельные металлы — Ca (2), Ba (4), Sr (5) (Be и Mg исключены!). В IIA-подгруппе основность растёт вниз (Ca(OH)2 < Sr(OH)2 < Ba(OH)2), значит в порядке ослабления: Ba → Sr → Ca → ответ: 452."}, {"id": "t14_max_so_nof", "type": "short", "sk": "oxides_hydroxides", "ref": "05.16", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) N   2) F   3) O   4) Na   5) Mg\nвыберите три элемента, которые находятся в одном периоде. Расположите выбранные элементы в порядке ВОЗРАСТАНИЯ их высшей степени окисления. Запишите 3 цифры без пробелов.", "a": "231", "ex": "Ловушка на 100 баллов! Во 2-м периоде лежат N (1), F (2), O (3). У фтора высшая СО равна 0 (в F2), у кислорода — +2 (в OF2), у азота — +5 (в HNO3). По возрастанию: F (0) < O (+2) < N (+5) → ответ: 231."}, {"id": "t15_lvs_acid_viia", "type": "short", "sk": "hydrides_lvs", "ref": "06.16", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) F   2) O   3) Cl   4) Br   5) S\nвыберите три элемента, которые находятся в одной главной подгруппе. Расположите выбранные элементы в порядке УСИЛЕНИЯ кислотных свойств их водородных соединений. Запишите 3 цифры без пробелов.", "a": "134", "ex": "В VIIA-подгруппе лежат F (1), Cl (3), Br (4). Их ЛВС — HF, HCl, HBr. Главный разворот в группе: сверху вниз радиус растёт, связь H—Hal слабеет, кислотность усиливается: HF < HCl < HBr → ответ: 134."}, {"id": "t16_lvs_acid_via_down", "type": "short", "sk": "hydrides_lvs", "ref": "08.11", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) S   2) O   3) Cl   4) Se   5) Na\nвыберите три элемента, относящихся к халькогенам (VIA). Расположите выбранные элементы в порядке ОСЛАБЛЕНИЯ кислотных свойств их водородных соединений. Запишите 3 цифры без пробелов.", "a": "412", "ex": "Халькогены: S (1), O (2), Se (4). Их ЛВС: H2O, H2S, H2Se. Кислотность ЛВС усиливается вниз (H2O < H2S < H2Se), значит в порядке ослабления: H2Se → H2S → H2O → ответ: 412."}, {"id": "t17_lvs_redox_3p", "type": "short", "sk": "hydrides_lvs", "ref": "06.18", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) P   2) S   3) Cl   4) Na   5) Al\nвыберите три элемента, образующих летучие водородные соединения. Расположите выбранные элементы в порядке УСИЛЕНИЯ восстановительных свойств их водородных соединений. Запишите 3 цифры без пробелов.", "a": "321", "ex": "ЛВС образуют неметаллы P (1, PH3), S (2, H2S), Cl (3, HCl). В периоде восстановительные свойства ЛВС растут справа налево (чем ниже ЭО неметалла, тем легче он отдаёт электроны в низшей СО): HCl < H2S < PH3 → ответ: 321."}, {"id": "t18_lvs_basic_va", "type": "short", "sk": "hydrides_lvs", "ref": "06.12", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) P   2) N   3) As   4) Si   5) C\nвыберите три элемента одной главной подгруппы. Расположите выбранные элементы в порядке ОСЛАБЛЕНИЯ основных свойств их водородных соединений. Запишите 3 цифры без пробелов.", "a": "213", "ex": "В VA-подгруппе стоят P (1), N (2), As (3). Их ЛВС: NH3, PH3, AsH3. Основные свойства (способность присоединять H^{+}) ослабевают сверху вниз: NH3 > PH3 > AsH3 → ответ: 213."}, {"id": "t19_lvs_valence_vs_minso", "type": "short", "sk": "kim2_algo", "ref": "08.11", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) C   2) N   3) O   4) K   5) Mg\nвыберите три элемента, образующих летучие водородные соединения. Расположите выбранные элементы в порядке ВОЗРАСТАНИЯ их валентности в летучем водородном соединении. Запишите 3 цифры без пробелов.", "a": "321", "ex": "ЛВС образуют C (1, CH4 — IV), N (2, NH3 — III), O (3, H2O — II). В порядке возрастания валентности (II → III → IV): O → N → C → ответ: 321."}, {"id": "t20_min_so_negative", "type": "short", "sk": "kim2_algo", "ref": "06.14", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) S   2) P   3) Cl   4) Ca   5) Fe\nвыберите три элемента-неметалла. Расположите выбранные элементы в порядке ВОЗРАСТАНИЯ их низшей степени окисления. Запишите 3 цифры без пробелов.", "a": "213", "ex": "Ловушка отрицательных чисел! Неметаллы: S (1, низшая СО −2), P (2, −3), Cl (3, −1). Алгебраически −3 < −2 < −1, поэтому в порядке возрастания: P → S → Cl → ответ: 213."}, {"id": "t21_diagonal_b_si_c", "type": "short", "sk": "special_corner", "ref": "07.12", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) B   2) Si   3) C   4) Ca   5) Fe\nвыберите три p-элемента. Расположите выбранные элементы в порядке УМЕНЬШЕНИЯ их электроотрицательности. Запишите 3 цифры без пробелов.", "a": "312", "ex": "p-элементы: B (1), Si (2), C (3). Через уголок C максимум ЭО у C (2,55); в диагональной паре B и Si переход в 3-й период снижает ЭО сильнее сдвига вправо: B (2,04) > Si (1,90). По уменьшению: C → B → Si → ответ: 312."}, {"id": "t22_d_elements_maxso", "type": "short", "sk": "special_corner", "ref": "07.4", "n": 2, "lvl": 3, "q": "Из указанных в ряду элементов:\n1) Sc   2) Ca   3) Mn   4) Ga   5) Cr\nвыберите три d-элемента. Расположите выбранные элементы в порядке ВОЗРАСТАНИЯ их высшей степени окисления. Запишите 3 цифры без пробелов.", "a": "153", "ex": "Ca — s-элемент, Ga — p-элемент (ловушка 4-го периода!). Три d-элемента: Sc (1, IIIБ, +3), Cr (5, VIБ, +6), Mn (3, VIIБ, +7). По возрастанию высшей СО: Sc (+3) < Cr (+6) < Mn (+7) → ответ: 153."}, {"id": "t23_filter_p_traps", "type": "multi", "sk": "special_corner", "ref": "07.15", "n": 2, "lvl": 3, "q": "Отработка фильтра КИМ № 2: выберите из ряда ровно ТРИ p-элемента (остерегайтесь ловушек He и 4-го периода!).", "o": ["He", "Ga", "Cr", "Ge", "S"], "a": [1, 3, 4], "ex": "He (1s²) — s-элемент! Cr ([Ar]3d⁵4s¹) — d-элемент. К p-элементам относятся Ga (4p¹), Ge (4p²) и S (3p⁴)."}, {"id": "t24_filter_lvs", "type": "multi", "sk": "hydrides_lvs", "ref": "06.4", "n": 2, "lvl": 2, "q": "Отработка фильтра КИМ № 2: выберите из ряда ровно ТРИ элемента, образующих летучие водородные соединения (ЛВС).", "o": ["Na", "Se", "Ca", "P", "Br"], "a": [1, 3, 4], "ex": "Na и Ca — активные металлы (образуют твёрдые ионные гидриды NaH и CaH2). Летучие водородные соединения образуют неметаллы IVA–VIIA: Se (H2Se), P (PH3) и Br (HBr)."}, {"id": "t25_match_vectors", "type": "match", "sk": "kim2_algo", "ref": "08.8", "n": 2, "lvl": 2, "q": "Установите соответствие между характеристикой (для главных подгрупп) и направлением её УСИЛЕНИЯ / ВОЗРАСТАНИЯ в Периодической системе:", "left": ["А) Атомный радиус и основные свойства высших гидроксидов", "Б) Электроотрицательность и кислотные свойства высших гидроксидов", "В) Кислотные свойства летучих водородных соединений (ЛВС)", "Г) Восстановительные свойства летучих водородных соединений (ЛВС)"], "right": ["1) Вправо по периоду и ВВЕРХ по группе (к F)", "2) Влево по периоду и ВНИЗ по группе (к Fr/Cs)", "3) Вправо по периоду и ВНИЗ по группе (главный разворот!)", "4) Влево по периоду и ВНИЗ по группе (HCl < H2S < PH3; HF < HI)"], "a": [1, 0, 2, 3], "ex": "А → к Fr (влево и вниз); Б → к F (вправо и вверх); В → кислотность ЛВС растёт вправо и ВНИЗ; Г → восстановительность ЛВС растёт влево и вниз."}, {"id": "t26_match_exceptions", "type": "match", "sk": "kim2_algo", "ref": "08.12", "n": 2, "lvl": 3, "q": "Установите соответствие между элементом-ловушкой и главным правилом поведения этого элемента в задании № 2 ЕГЭ:", "left": ["А) Фтор (F)", "Б) Гелий (He)", "В) Литий (Li)", "Г) Кислород (O)"], "right": ["1) Относится к s-элементам (1s²), не включается в ряды по ЭО", "2) Не образует оксидов (OF2 — фторид кислорода), высшая СО = 0", "3) В IA-подгруппе уступает Na и K по восстановительным свойствам (Периодический закон)", "4) Электроотрицательнее хлора Cl (2-е место после F), высшая СО = +2"], "a": [1, 0, 2, 3], "ex": "F → нет оксидов, высшая СО = 0; He → s-элемент без ЭО; Li → слабее Na и K в № 2; O → ЭО выше Cl (3,44 > 3,16), высшая СО = +2."}], "subjectSlug": "chemistry", "_kim": {"2": {"b": 1, "l": "Б"}}, "_kon": {"01": {"t": "Модуль 01. Периодический закон и чтение чёрно-белой таблицы ФИПИ", "x": "Свойства элементов и их соединений периодически повторяются не из-за атомной массы, а из-за роста **заряда ядра Z** — вместе с ним закономерно повторяется строение внешнего электронного слоя. А на самом ЕГЭ главный инструмент — короткопериодная чёрно-белая таблица ФИПИ, где подгруппы А и Б различаются по **сдвигу символа в ячейке**."}, "01.1": {"t": "Модуль 01 · Главная мысль.", "x": "Свойства элементов и их соединений периодически повторяются не из-за атомной массы, а из-за роста **заряда ядра Z** — вместе с ним закономерно повторяется строение внешнего электронного слоя. А на самом ЕГЭ главный инструмент — короткопериодная чёрно-белая таблица ФИПИ, где подгруппы А и Б различаются по **сдвигу символа в ячейке**."}, "01.5": {"t": "Модуль 01 · 1. Физический смысл Периодического закона", "x": "• **Ar и K** — Порядковый номер Z: 18 и 19; Атомная масса Ar: 39,95 > 39,10; Почему порядок именно такой: Ar — инертный газ (VIIIA), K — щелочной металл (IA); заряд ядра Ar (+18) меньше, чем у K (+19)\n• **Co и Ni** — Порядковый номер Z: 27 и 28; Атомная масса Ar: 58,93 > 58,69; Почему порядок именно такой: У кобальта преобладает тяжёлый изотоп ^{59}Co, но заряд ядра +27 меньше, чем +28 у никеля\n• **Te и I** — Порядковый номер Z: 52 и 53; Атомная масса Ar: 127,60 > 126,90; Почему порядок именно такой: Te — аналог серы (VIA), I — галоген (VIIA); заряд ядра теллура +52 меньше, чем +53 у иода"}, "01.13": {"t": "Модуль 01 · 2. Как читать чёрно-белую таблицу ФИПИ без ошибок", "x": "• **[[Период|Периоды]] (горизонтальные ряды 1–7):** периоды 1, 2 и 3 — *малые* (состоят из одной строки), периоды 4–7 — *большие* (состоят из двух строк: чётной и нечётной). Номер периода строго равен **числу энергетических уровней** в атоме.\n• **[[Группа|Группы]] (вертикальные столбцы I–VIII):** каждая группа делится на **главную (А)** и **побочную (Б)** подгруппы. В 1–3-м периодах стоят только элементы главных подгрупп, а элементы побочных подгрупп появляются начиная с 4-го периода.…"}, "01.17": {"t": "Модуль 01 · 3. Разбор вслух: первичный отбор элементов по таблице ФИПИ", "x": "**Шаг 1. Выписываем координаты каждого элемента по таблице ФИПИ.** K — 4-й период, IA (s-металл); Cr — 4-й период, VIБ (d-металл); Se — 4-й период, VIA (p-неметалл); Br — 4-й период, VIIA (p-неметалл); O — 2-й период, VIA (p-неметалл).\n**Шаг 2. Проверяем возможные фильтры задания № 2.** Если условие просит *«три элемента, находящихся в одной группе»* — это Cr (VIБ), Se (VIA) и O (VIA): все трое в VI группе, хотя Cr в побочной! Если же условие уточняет *«три p-элемента»* или *«три неметалла»* — Cr отпадает, остаются Se, Br, O.\n**Шаг 3. Проверяем фильтр по периоду.** Если в условии *«три элемента, находящихся в одном периоде»* (и например, в ряде было бы 3 элемента 4-го периода, а два из 2-го), смотрим строго на номер периода — и помним, что в большом 4-м периоде **две строки** (K–Ni в верхней и Cu–Kr в нижней): K, Cr, Se и Br все лежат в одном 4-м периоде!"}, "01.18": {"t": "Модуль 01 · Ловушки таблицы ФИПИ", "x": "**Три частые ошибки при чтении таблицы ФИПИ:**\n1. **Большой период из двух строк:** K (верхняя строка 4-го периода) и Br (нижняя строка 4-го периода) находятся в **одном 4-м периоде**, а не в разных!\n2. **Гелий He:** стоит в VIIIA группе, но имеет конфигурацию 1s² — это **s-элемент**, а не p-элемент.\n3. **Группа vs главная подгруппа:** слова *«в одной группе»* объединяют элементы А и Б одного столбца (например, O, S, Cr), а слова *«в одной главной подгруппе»* — только элементы А (O, S, Se)."}, "02": {"t": "Модуль 02. Атомный радиус и энергия ионизации", "x": "Все периодические закономерности вырастают из **атомного радиуса**. По периоду слева направо число слоёв не меняется, а заряд ядра растёт — облако **сжимается** (радиус убывает). По группе сверху вниз добавляются новые электронные слои — атом **расширяется** (радиус растёт). Чем меньше радиус, тем сильнее ядро держит внешний электрон и тем выше энергия ионизации."}, "02.1": {"t": "Модуль 02 · Главная мысль.", "x": "Все периодические закономерности вырастают из **атомного радиуса**. По периоду слева направо число слоёв не меняется, а заряд ядра растёт — облако **сжимается** (радиус убывает). По группе сверху вниз добавляются новые электронные слои — атом **расширяется** (радиус растёт). Чем меньше радиус, тем сильнее ядро держит внешний электрон и тем выше энергия ионизации."}, "02.6": {"t": "Модуль 02 · 1. Почему атом сжимается в периоде и растёт в группе", "x": "Отсюда сразу следует правило для всей таблицы Менделеева: **атомный радиус увеличивается справа налево по периоду и сверху вниз по группе** — то есть в сторону **франция Fr / цезия Cs** (нижний левый угол таблицы). Самые маленькие атомы находятся в правом верхнем углу (H, He, F)."}, "02.9": {"t": "Модуль 02 · 2. Энергия ионизации — прямое следствие радиуса", "x": "• **В периоде слева направо** энергия ионизации **растёт** (от щелочного металла к благородному газу): легче всего оторвать электрон у Li или Na, труднее всего — у Ne и Ar.\n• **В главной подгруппе сверху вниз** энергия ионизации **убывает**: у Cs внешний электрон 6s¹ далеко от ядра и экранирован пятью слоями, поэтому отрывается намного легче, чем 2s¹ у Li."}, "02.12": {"t": "Модуль 02 · 3. Разбор вслух: реальное задание № 2 из Демоверсии ЕГЭ-2027", "x": "Разберём точное задание № 2 из утверждённой Демоверсии ЕГЭ-2027. Дан ряд элементов: 1) O   2) F   3) Al   4) Si   5) Li. Условие: *«Выберите три элемента, которые в Периодической системе находятся в одном периоде. Расположите выбранные элементы в порядке возрастания их атомных радиусов»*."}, "02.16": {"t": "Модуль 02 · 4. Границы правила и тонкости на 95–100 баллов", "x": "• ****Изоэлектронные ионы** (O^{2−}, F^{−}, Na^{+}, Mg^{2+}, Al^{3+})** — Как работает на самом деле: У всех ровно по 10 электронов (1s²2s²2p⁶), но заряд ядра растёт от +8 до +13; Что нужно знать для ЕГЭ: Чем выше Z при том же числе электронов, тем **меньше радиус**: r(O^{2−}) > r(F^{−}) > r(Na^{+}) > r(Mg^{2+}) > r(Al^{3+}). Катион всегда меньше своего атома (Na^{+} < Na), анион — больше (Cl^{−} > Cl).\n• ****[[d-сжатие|d-сжатие]]** (Sc–Zn и пара Al / Ga)** — Как работает на самом деле: У d-элементов электроны идут на предвнешний 3d-уровень и экранируют рост Z, поэтому радиус от Cr до Cu почти не меняется, а Ga (135 пм) даже чуть меньше Al (143 пм); Что нужно знать для ЕГЭ: В КИМ № 2 элементы с аномальной парой Al и Ga на сравнение радиуса не ставят, но понимать, почему у d-металлов радиус меняется плавнее, важно.…"}, "03": {"t": "Модуль 03. Электроотрицательность и её подводные камни", "x": "**Электроотрицательность (ЭО)** — это сила, с которой атом в химическом соединении перетягивает к себе общие электроны. Она растёт **к фтору** (слева направо по периоду и снизу вверх по группе), у благородных газов на ЕГЭ считается нулевой, а **водород (2,20)** стоит между фосфором и углеродом — это ключ ко многим заданиям № 2 и № 3."}, "03.1": {"t": "Модуль 03 · Главная мысль.", "x": "**Электроотрицательность (ЭО)** — это сила, с которой атом в химическом соединении перетягивает к себе общие электроны. Она растёт **к фтору** (слева направо по периоду и снизу вверх по группе), у благородных газов на ЕГЭ считается нулевой, а **водород (2,20)** стоит между фосфором и углеродом — это ключ ко многим заданиям № 2 и № 3."}, "03.6": {"t": "Модуль 03 · 1. Что такое электроотрицательность и почему она растёт к фтору", "x": "Схема изменения электроотрицательности и точное положение водорода H (2,20) среди неметаллов по шкале Полинга."}, "03.9": {"t": "Модуль 03 · 2. Три подводных камня ЭО на 95–100 баллов", "x": "• **Благородные газы (He, Ne, Ar, Kr) не возглавляют ряд ЭО:** у них уже завершённый внешний слой (1s² или ns²np⁶), они не стремятся притягивать электроны в обычных химических связях. Поэтому на ЕГЭ их ЭО считают равной нулю / неопределённой, а абсолютным чемпионом остаётся **фтор F**.\n• **Место водорода H (2,20):** хотя H стоит в IA группе над щелочными металлами, по электроотрицательности он — типичный неметалл! Он **электроотрицательнее** всех металлов, а также кремния (Si 1,90) и бора (B 2,04), но **менее электроотрицателен**, чем углерод (C 2,55), сера (S 2,58), азот (N 3,04), кислород (O 3,44) и галогены (F, Cl, Br, I). Именно поэтому в метане CH4 углерод имеет степень окисления −4 (а H +1), а в силане SiH4 кремний имеет +4 (а H −1)!…"}, "03.11": {"t": "Модуль 03 · 3. Разбор вслух: сравнение ЭО в разных ситуациях", "x": "Допустим, дан ряд: 1) P   2) S   3) O   4) Al   5) Mg. Условие: *«Выберите три неметалла и расположите их в порядке возрастания электроотрицательности»*."}, "03.13": {"t": "Модуль 03 · Ловушка на 100 баллов: O сильнее Cl", "x": "**Ошибка с кислородом и хлором:** ученики иногда думают, что раз Cl стоит правее O (в VIIA группе, а O в VIA), то у хлора ЭО выше. Нет! O лежит во 2-м периоде (2 слоя, радиус заметно меньше), а Cl — в 3-м периоде (3 слоя). По шкале Полинга O (3,44) > Cl (3,16) — кислород уступает по ЭО **только фтору F**!"}, "04": {"t": "Модуль 04. Металлические, неметаллические и окислительно-восстановительные свойства", "x": "В задании № 2 две пары терминов работают как точные синонимы: **металлические свойства = восстановительные свойства** (легко отдавать e⁻, растут к **Fr/Cs**) и **неметаллические свойства = окислительные свойства** (сильно притягивать e⁻, растут к **F**). Всё сводится к одному компасу с двумя противоположными стрелками."}, "04.1": {"t": "Модуль 04 · Главная мысль.", "x": "В задании № 2 две пары терминов работают как точные синонимы: **металлические свойства = восстановительные свойства** (легко отдавать e⁻, растут к **Fr/Cs**) и **неметаллические свойства = окислительные свойства** (сильно притягивать e⁻, растут к **F**). Всё сводится к одному компасу с двумя противоположными стрелками."}, "04.8": {"t": "Модуль 04 · 2. Как это проявляется у реальных простых веществ", "x": "• **Щелочные металлы (IA):** сверху вниз восстановительные свойства растут (Li < Na < K < Rb < Cs). Литий реагирует с водой спокойно, натрий плавится в шарик и бегает по поверхности, калий вспыхивает фиолетовым пламенем, а цезий реагирует со взрывом: 2Na + 2H2O → 2NaOH + H2.\n• **Галогены (VIIA):** сверху вниз окислительные свойства ослабевают (F2 > Cl2 > Br2 > I2). Поэтому более сильный окислитель вытесняет более слабый из растворов его солей: Cl2 + 2KBr → 2KCl + Br2, Br2 + 2KI → 2KBr + I2. Единственное исключение в водном растворе — фтор F2: он настолько сильный окислитель, что окисляет саму воду (2F2 + 2H2O → 4HF + O2), поэтому вытеснять хлор из водного раствора NaCl им нельзя.\n• **По 3-му периоду слева направо (Na → Mg → Al → Si → P → S → Cl):** от активного металла-восстановителя Na через амфотерный Al и неметаллы Si, P, S мы приходим к сильному окислителю Cl2."}, "04.10": {"t": "Модуль 04 · 3. Разбор вслух: работа с формулировками на ОВ-свойства", "x": "Рассмотрим типичный ряд КИМ № 2: 1) Na   2) Mg   3) K   4) Ca   5) Al. Условие: *«Выберите три элемента, которые находятся в одном периоде, и расположите их в порядке усиления восстановительных свойств соответствующих им простых веществ»*."}, "04.13": {"t": "Модуль 04 · Критическая ловушка: литий против калия", "x": "**Ловушка № 1: Ряд напряжений металлов (Li левее K) vs Периодический закон (Li < Na < K)!**\nВ электрохимическом ряду напряжений (который выдан на бланке ЕГЭ под таблицей растворимости) литий Li стоит **левее** K и Na. Почему? Потому что ряд напряжений измеряет электродный потенциал **в водном растворе**, где крошечный ион Li^{+} выделяет огромную энергию гидратации (притягивает к себе молекулы воды), что смещает равновесие в пользу окисления Li.\nНо в **Задании № 2** проверяется **Периодический закон** (свойства атомов и простых веществ в таблице Менделеева): в IA-подгруппе металлические и восстановительные свойства строго **растут сверху вниз**: **Li < Na < K < Rb < Cs**! Не подсматривай порядок щелочных металлов в ряду напряжений при решении № 2!"}, "05": {"t": "Модуль 05. Высшие оксиды и высшие гидроксиды: кислотность и основность", "x": "В терминах ЕГЭ **высший гидроксид** — это не только основание металла (NaOH), но и **высшая кислородсодержащая кислота неметалла** (H2SO4, HNO3, H3PO4, HClO4). Кислотные свойства высших оксидов и гидроксидов меняются **так же, как неметаллические свойства** (растут к F), а основные — **так же, как металлические** (растут к Fr)."}, "05.1": {"t": "Модуль 05 · Главная мысль.", "x": "В терминах ЕГЭ **высший гидроксид** — это не только основание металла (NaOH), но и **высшая кислородсодержащая кислота неметалла** (H2SO4, HNO3, H3PO4, HClO4). Кислотные свойства высших оксидов и гидроксидов меняются **так же, как неметаллические свойства** (растут к F), а основные — **так же, как металлические** (растут к Fr)."}, "05.3": {"t": "Модуль 05 · 1. Что называют высшим оксидом и высшим гидроксидом", "x": "[[Высший оксид]] — это оксид, в котором элемент находится в своей **высшей степени окисления**. Для большинства элементов главных подгрупп высшая степень окисления равна **номеру группы**: у натрия (IA) — Na2O (+1), у алюминия (IIIA) — Al2O3 (+3), у серы (VIA) — SO3 (+6), у хлора (VIIA) — Cl2O7 (+7)."}, "05.11": {"t": "Модуль 05 · 3. Закономерности по периоду, по группе и по степени окисления", "x": "• **Na (IA)** — Высший оксид: Na2O; Высший гидроксид: NaOH; Характер и сила: Сильное основание (щёлочь)\n• **Mg (IIA)** — Высший оксид: MgO; Высший гидроксид: Mg(OH)2; Характер и сила: Слабое нерастворимое основание\n• **Al (IIIA)** — Высший оксид: Al2O3; Высший гидроксид: Al(OH)3; Характер и сила: Амфотерный гидроксид\n• **Si (IVA)** — Высший оксид: SiO2; Высший гидроксид: H2SiO3; Характер и сила: Очень слабая нерастворимая кислота\n• **P (VA)** — Высший оксид: P2O5; Высший гидроксид: H3PO4; Характер и сила: Кислота средней силы\n• **S (VIA)** — Высший оксид: SO3; Высший гидроксид: H2SO4; Характер и сила: Сильная кислота\n• **Cl (VIIA)** — Высший оксид: Cl2O7; Высший гидроксид: HClO4; Характер и сила: Одна из сильнейших кислот"}, "05.12": {"t": "Модуль 05 · 3. Закономерности по периоду, по группе и по степени окисления", "x": "• **В периоде слева направо:** основные свойства высших оксидов и гидроксидов **ослабевают**, а кислотные **усиливаются** (NaOH → Mg(OH)2 → Al(OH)3 → H2SiO3 → H3PO4 → H2SO4 → HClO4).\n• **В главной подгруппе сверху вниз (металлы):** основные свойства **усиливаются**: LiOH < NaOH < KOH < RbOH < CsOH; Be(OH)2 (амф.) → Mg(OH)2 (слаб. осн.) → Ca(OH)2 < Sr(OH)2 < Ba(OH)2 (сильные щёлочи).\n• **В главной подгруппе сверху вниз (неметаллы):** кислотные свойства высших оксидов и высших гидроксидов **ослабевают** (радиус атома Э растёт, он хуже стягивает электроны с O—H): H2CO3 > H2SiO3; HNO3 > H3PO4 > H3AsO4; H2SO4 > H2SeO4; HClO4 > HBrO4 > H5IO6.…"}, "05.14": {"t": "Модуль 05 · 4. Разбор вслух: задание на высшие гидроксиды", "x": "Дан ряд элементов: 1) P   2) N   3) As   4) F   5) O. Условие: *«Выберите три элемента, которые находятся в одной главной подгруппе, и расположите их в порядке усиления кислотных свойств их высших гидроксидов»*."}, "05.16": {"t": "Модуль 05 · Границы правила на 100 баллов", "x": "**Три коварные ловушки с высшими оксидами, степенями окисления и валентностью:**\n1. **Исключения по высшей степени окисления и высшей валентности (F, O, N):** у **фтора F** нет положительных степеней окисления — его высшая степень окисления равна **0** (в F2), а высшая валентность — **I**. У **кислорода O** высшая степень окисления равна **+2** (в OF2), а высшая валентность в школьном курсе — **II** (до III за счёт донорно-акцепторной связи в CO, H3O^{+}). У **азота N** высшая степень окисления **+5** (N2O5, HNO3), но **высшая валентность равна IV** (на 2-м уровне нет 2d-орбиталей). Поэтому в 2-м периоде по возрастанию высшей степени окисления тройка F, O, N выстраивается так: **F (0) < O (+2) < N (+5)**!…"}, "06": {"t": "Модуль 06. Водородные соединения: главный разворот тренда в группе", "x": "Это **главная ловушка всего задания № 2**: у высших кислородсодержащих кислот кислотность в группе сверху вниз **убывает** (HClO4 > HBrO4), а у **летучих водородных соединений (бескислородных кислот)** кислотность сверху вниз **УСИЛИВАЕТСЯ** (HF < HCl < HBr < HI; H2O < H2S < H2Se < H2Te)!"}, "06.1": {"t": "Модуль 06 · Главная мысль.", "x": "Это **главная ловушка всего задания № 2**: у высших кислородсодержащих кислот кислотность в группе сверху вниз **убывает** (HClO4 > HBrO4), а у **летучих водородных соединений (бескислородных кислот)** кислотность сверху вниз **УСИЛИВАЕТСЯ** (HF < HCl < HBr < HI; H2O < H2S < H2Se < H2Te)!"}, "06.4": {"t": "Модуль 06 · Гидриды металлов vs Летучие водородные соединения (ЛВС)", "x": "• **Кто образует** — Гидриды металлов: Активные металлы IA и IIA групп (LiH, NaH, KH, CaH2, BaH2); Летучие водородные соединения (ЛВС): Неметаллы IVA–VIIA групп (CH4, SiH4, NH3, PH3, H2O, H2S, H2Se, HF, HCl, HBr, HI); Почему важно: Определяет фильтр «образуют ЛВС» в КИМ № 2\n• **Степень окисления H** — Гидриды металлов: H^{−1} (водород электроотрицательнее металла); Летучие водородные соединения (ЛВС): H^{+1} (кроме SiH4, где ЭО H > Si, поэтому Si^{+4}H4^{−1}); Почему важно: В гидридах металлов водород выступает сильным восстановителем\n• **Строение и свойства** — Гидриды металлов: Твёрдые ионные солеподобные кристаллы; бурно реагируют с водой: CaH2 + 2H2O → Ca(OH)2 + 2H2; Летучие водородные соединения (ЛВС): Газы или жидкости при н.у. с ковалентной полярной связью; в воде дают бескислородные кислоты (HCl, H2S) или основания (NH3); Почему важно: Именно ЛВС сравнивают по кислотности, основности и устойчивости в № 2"}, "06.8": {"t": "Модуль 06 · 2. Почему в группе сверху вниз кислотность ЛВС разворачивается", "x": "1. **В периоде (слева направо, например CH4 → NH3 → H2O → HF или SiH4 → PH3 → H2S → HCl):** радиус атома Э меняется сравнительно слабо, но **резко растёт его электроотрицательность**. Связь Э—H становится всё полярнее, на водороде растёт частичный положительный заряд δ+ → протон H^{+} отщепляется всё легче → **кислотные свойства ЛВС усиливаются** (NH3 — основание → H2O — нейтральна → HF — слабая кислота; PH3 → H2S — слабая кислота → HCl — сильная кислота).\n2. **В группе (сверху вниз, например HF → HCl → HBr → HI или H2O → H2S → H2Se → H2Te):** добавляются новые электронные слои, **радиус атома Э резко растёт**! Из-за этого длина связи H—Э сильно увеличивается, а её прочность падает. Оторвать протон H^{+} от огромного атома иода намного легче, чем от крошечного фтора (кроме того, молекулы HF в воде дополнительно сцеплены прочными водородными связями).…"}, "06.12": {"t": "Модуль 06 · 3. Все четыре свойства ЛВС в одной таблице", "x": "• ****Кислотные свойства**** — В периоде (слева → направо): **Усиливаются** (NH3 < H2O < HF; PH3 < H2S < HCl); В группе (сверху → вниз): **Усиливаются** (HF < HCl < HBr < HI; H2O < H2S < H2Se); Почему так происходит: Вправо растёт полярность H—Э; вниз растёт радиус Э и связь H—Э рвётся легче\n• ****Основные свойства** (присоединение H^{+})** — В периоде (слева → направо): **Ослабевают** (NH3 > H2O > HF); В группе (сверху → вниз): **Ослабевают** (NH3 > PH3 > AsH3); Почему так происходит: У N в NH3 неподелённая пара на компактном 2p-уровне легко захватывает H^{+} → NH4^{+}; у PH3 облако размыто…"}, "06.14": {"t": "Модуль 06 · 3. Все четыре свойства ЛВС в одной таблице", "x": "• **Валентность неметалла в ЛВС** равна **8 − номер группы**: в периоде она **убывает слева направо** (CH4 IV → NH3 III → H2O II → HF I; SiH4 IV → PH3 III → H2S II → HCl I).\n• **Низшая (минимальная) степень окисления** равна **номер группы − 8** для неметаллов (C −4, N −3, O −2, F −1) и **0** для металлов. **Ловушка отрицательных чисел:** в порядке **возрастания** низшая СО идёт от −4 к 0 (−4 < −3 < −2 < −1 < 0, то есть слева направо по периоду), а не по модулю!"}, "06.16": {"t": "Модуль 06 · 4. Разбор вслух: два классических задания на ЛВС", "x": "**Задача А (группа):** из ряда 1) F   2) O   3) Cl   4) Br   5) S выберите три элемента одной главной подгруппы и расположите их в порядке **усиления кислотных свойств** их водородных соединений."}, "06.18": {"t": "Модуль 06 · 4. Разбор вслух: два классических задания на ЛВС", "x": "**Задача Б (период):** из ряда 1) P   2) S   3) Cl   4) Na   5) Al выберите три элемента, образующих летучие водородные соединения, и расположите их в порядке **усиления восстановительных свойств** их водородных соединений."}, "06.20": {"t": "Модуль 06 · Ловушка на 100 баллов", "x": "**Скрытый капкан с бором и углеродом:**\n• Бор (B, IIIA) образует не мономер BH3, а диборан B2H6; в классической таблице ЛВС школьного курса (IVA–VIIA) его обычно не ставят в один ряд с галогеноводородами.\n• Метан CH4 и силан SiH4 в воде практически не проявляют кислотных свойств, поэтому в рядах на кислотность ЛВС в периоде ФИПИ чаще всего берёт элементы VA–VIIA (NH3, H2O, HF или PH3, H2S, HCl).\n• Не путай **кислотные свойства HClO4 vs HBrO4** (высшие гидроксиды: Cl > Br) и **кислотные свойства HCl vs HBr** (водородные соединения: Cl < Br)!"}, "07": {"t": "Модуль 07. Особые случаи: d-элементы, водород, инертные газы и угловое сравнение", "x": "Простые правила «к F» и «к Fr» идеально работают для **главных подгрупп (А)**. Как только в задании появляются d-элементы, водород H, благородные газы или тройка элементов «не на одной линии», включаются четыре особых правила этого модуля — они закрывают самые коварные варианты № 2."}, "07.1": {"t": "Модуль 07 · Главная мысль.", "x": "Простые правила «к F» и «к Fr» идеально работают для **главных подгрупп (А)**. Как только в задании появляются d-элементы, водород H, благородные газы или тройка элементов «не на одной линии», включаются четыре особых правила этого модуля — они закрывают самые коварные варианты № 2."}, "07.4": {"t": "Модуль 07 · 1. Особенности d-элементов и побочных подгрупп (Б)", "x": "• **Внутри 4-го периода (Sc → Zn):** электроны поступают не на внешний 4s-уровень, а на **предвнешний 3d-подуровень**, поэтому внешняя оболочка почти не меняется (4s², у Cr и Cu — 4s¹). Из-за [[d-сжатие|d-сжатия]] атомный радиус уменьшается очень плавно, а не резко, как у s- и p-элементов.\n• **Высшая степень окисления в ряду Sc → Zn:** растёт от Sc (+3) до Mn (+7), совпадая с номером группы (Sc +3, Ti +4, V +5, Cr +6, Mn +7), и вместе с ней растут кислотные свойства высших оксидов (Sc2O3 амф. → CrO3 кисл. → Mn2O7 очень сильный кисл.). Но дальше у Fe (макс. +6, а не +8), Co (+3), Ni (+2/+3), Cu (+2), Zn (+2) высшая степень окисления **не равна номеру группы**!…"}, "07.12": {"t": "Модуль 07 · 4. Разбор вслух: отбор p-элементов (уголок и диагональная пара)", "x": "Дан ряд: 1) B   2) Si   3) C   4) Ca   5) Fe. Условие: *«Выберите три p-элемента и расположите их в порядке уменьшения электроотрицательности»*."}, "07.14": {"t": "Модуль 07 · Тонкость диагональных пар", "x": "**Когда на ЕГЭ попадается «диагональная» пара вроде B и Si или P и C:** переход на новый период (добавление целого электронного слоя) обычно влияет на радиус и ЭО **сильнее**, чем сдвиг на 1 клетку по периоду. Поэтому r(Si) > r(B) и ЭО(B) > ЭО(Si), а в паре C и P: r(P) > r(C) и ЭО(C) > ЭО(P). Но для полной надёжности сверяйся со шкалой Полинга из модуля 03!"}, "07.15": {"t": "Модуль 07 · Мост к КИМ (№ 2 КИМ (семейства s/p/d и угловые ряды))", "x": "**Как спрашивают:** Выберите три s- / p- / d-элемента и расположите их в порядке возрастания / уменьшения свойства…\n**На чём ловят:** Гелий He — это s-элемент; Ga и Ge в 4-м периоде — p-элементы (а не d); в «уголке» элементы не лежат на одной линии, но соединяются через углового посредника.\n**Как читать:** Если три элемента не лежат в одной строке и не в одном столбце — поставь их точками на маленькой сетке 2×2 прямо на полях КИМ и проведи стрелки по периоду и группе."}, "08": {"t": "Модуль 08. Все формулировки задания № 2 КИМ и безошибочный алгоритм", "x": "Главное техническое отличие задания № 2 от заданий № 1, 3 и 4: **порядок трёх цифр в ответе строго важен**! Если выбрать правильную тройку, но перепутать «возрастание» и «убывание», компьютер поставит **0 баллов**. Поэтому решение всегда идёт в 4 жёстких шага: *Фильтр (3 из 5) → Формулы / координаты → Стрелка тренда → Проверка направления*."}, "08.1": {"t": "Модуль 08 · Главная мысль.", "x": "Главное техническое отличие задания № 2 от заданий № 1, 3 и 4: **порядок трёх цифр в ответе строго важен**! Если выбрать правильную тройку, но перепутать «возрастание» и «убывание», компьютер поставит **0 баллов**. Поэтому решение всегда идёт в 4 жёстких шага: *Фильтр (3 из 5) → Формулы / координаты → Стрелка тренда → Проверка направления*."}, "08.4": {"t": "Модуль 08 · 1. Полная карта формулировок КИМ № 2", "x": "• **6 фильтров отбора (3 из 5)** — • В **одном периоде** (помни: большой период занимает 2 строки!).; • В **одной группе** (А + Б) или **одной главной подгруппе** (только А).; • Одного электронного семейства: **s-, p- или d-элементы** (He — это s!).; • **Металлы** или **неметаллы** (по диагонали B–Si–As–Te–At, все Б — металлы), а также тривиальные группы: **щелочные** (Li–Fr), **щёлочноземельные** (Ca, Sr, Ba, Ra, без Be и Mg), **халькогены** (VIA), **галогены** (VIIA).; • Образуют **летучие водородные соединения** (неметаллы IVA–VIIA) или **высшие оксиды** (исключаем F, O, инертные газы).; • Элементы **малых** (1–3) или **больших** (4–7) периодов.…"}, "08.8": {"t": "Модуль 08 · 3. Сводная шпаргалка всех трендов в одном взгляде", "x": "• **Атомный радиус** — В периоде (слева → направо): Убывает ↓; В группе (сверху → вниз): Возрастает ↑; Ориентир: К Fr\n• **Энергия ионизации** — В периоде (слева → направо): Возрастает ↑; В группе (сверху → вниз): Убывает ↓; Ориентир: К He/F\n• **Электроотрицательность (ЭО)** — В периоде (слева → направо): Возрастает ↑; В группе (сверху → вниз): Убывает ↓; Ориентир: К F (без VIIIA)\n• **Металлические / восстановительные свойства** — В периоде (слева → направо): Ослабевают ↓; В группе (сверху → вниз): Усиливаются ↑; Ориентир: К Fr (Li < Na < K)\n• **Неметаллические / окислительные свойства** — В периоде (слева → направо): Усиливаются ↑; В группе (сверху → вниз): Ослабевают ↓; Ориентир: К F (без VIIIA)\n• **Основные свойства высших оксидов и гидроксидов** — В периоде (слева → направо): Ослабевают ↓; В группе (сверху → вниз): Усиливаются ↑; Ориентир: К Fr (Ba(OH)2 > Mg(OH)2)…"}, "08.11": {"t": "Модуль 08 · 4. Четыре полных разбора разных типов КИМ № 2", "x": "**Шаг 1.** **Кейс 1 (Демо ЕГЭ-2027 · радиус в периоде):** ряд 1) O  2) F  3) Al  4) Si  5) Li. *Три элемента в одном периоде → в порядке возрастания атомных радиусов.* Во 2-м периоде лежат O (1), F (2), Li (5). Радиус растёт к Fr (справа налево), значит от меньшего к большему: F → O → Li → **215**.\n**Шаг 2.** **Кейс 2 (разворот ЛВС в группе):** ряд 1) S  2) O  3) Cl  4) Se  5) Na. *Три элемента одной главной подгруппы → в порядке ослабления кислотных свойств их водородных соединений.* В VIA лежат S (1), O (2), Se (4); их ЛВС — H2S, H2O, H2Se. Кислотность ЛВС растёт вниз (H2O < H2S < H2Se), значит в порядке **ослабления** (от сильной к слабой): H2Se → H2S → H2O → **412**.…"}, "08.12": {"t": "Модуль 08 · Последняя проверка перед бланком", "x": "**Словарь-переключатель направления (проверяй ПЕРЕД переносом в бланк!):**\n• **Возрастание = увеличение = усиление** → от МЕНЬШЕГО к БОЛЬШЕМУ (слабый → средний → сильный).\n• **Убывание = уменьшение = ослабление** → от БОЛЬШЕГО к МЕНЬШЕМУ (сильный → средний → слабый).\nВ ответе на № 2 **перестановка любых двух цифр = 0 баллов**, даже если все три элемента выбраны верно!"}}, "_kt": "Задание 2 · Периодический закон и свойства элементов", "_mods": {"01": "Периодический закон и чтение чёрно-белой таблицы ФИПИ", "02": "Атомный радиус и энергия ионизации", "03": "Электроотрицательность и её подводные камни", "04": "Металлические, неметаллические и окислительно-восстановительные свойства", "05": "Высшие оксиды и высшие гидроксиды: кислотность и основность", "06": "Водородные соединения: главный разворот тренда в группе", "07": "Особые случаи: d-элементы, водород, инертные газы и угловое сравнение", "08": "Все формулировки задания № 2 КИМ и безошибочный алгоритм"}, "_skm": {"law_pshe": ["01"], "radius_ioniz": ["02"], "electroneg": ["03"], "metal_redox": ["04"], "oxides_hydroxides": ["05"], "hydrides_lvs": ["06"], "special_corner": ["07"], "kim2_algo": ["08"]}, "_fig": []};
